(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0020.js"] = [{"id":"poem-82edbf0ff836bb580272e8c6","title":"满庭芳·山抹微云","author":"秦观","dynasty":"宋","verses":["山抹微云，天连衰草，画角声断谯门。","暂停征棹，聊共引离尊。","多少蓬莱旧事，空回首、烟霭纷纷。","斜阳外，寒鸦万点，流水绕孤村。","销魂。","当此际，香囊暗解，罗带轻分。","谩赢得、青楼薄名存。","此去何时见也，襟袖上、空惹啼痕。","伤情处，高城望断，灯火已黄昏。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-67","tags":["宋词三百首"]},{"id":"poem-82f562db2f95444e5ed339fc","title":"长相思·一重山","author":"李煜","dynasty":"五代","verses":["一重山，两重山。","山远天高烟水寒，相思枫叶丹。","菊花开，菊花残。","寒雁高飞人未还，一帘风月闲。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-38","tags":[]},{"id":"poem-82f89ef592082cf4b065503a","title":"无生庵","author":"华镇","dynasty":"宋","verses":["大士今何在，空山旧隠存。","百年闲藓径，终日敞尘阍。","砌暖晴添草，窗寒暝叫猿。","当时团坐客，相顾竟何言。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-e46e7a32-8d60-4aea-8dbc-0913eade5b70","tags":[]},{"id":"poem-82f8af7e18c543c984c8a2da","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二","author":"易静","dynasty":"唐","verses":["为术者，太乙式（辛本、川本作「遁」）须知。","起造凶丧须得此，出行莅任动兵机，用者得便宜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-c78ca668-24ae-447f-9bb9-0573fd79b736","tags":[]},{"id":"poem-82fe168d4a0f89a85e514dae","title":"郊庙歌辞 仪坤庙乐章 舒和","author":"胡雄","dynasty":"唐","verses":["送文迎武递参差，一始一终光圣仪。","四海生人歌有庆，千龄孝享肃无亏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-0b15d19b-79e5-4872-8e52-77d26c711632","tags":[]},{"id":"poem-8319fc3926add499685d2dd4","title":"破阵子","author":"施惠《幽闺记》","dynasty":"元","verses":["(老旦上)况是君臣分散。","那堪母子临危。","(旦上)严父东行何日返？天子南迁甚日回？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2923","tags":[]},{"id":"poem-831ecec89ede57098883902f","title":"至德二载甫自京金光门出问道归凤翔乾元初从左拾遗移华州掾与亲故别因出此门有悲往事","author":"杜甫","dynasty":"唐","verses":["此道昔归顺，西郊胡正繁。","至今残破胆，应有未招魂。","近得归京邑，移官岂至尊。","无才日衰老，驻马望千门。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f88a6dbd-bf83-458c-b5e2-85fdd1ed98b2","tags":["唐诗三百首","岁月","五言律诗","怀念"]},{"id":"poem-8320b0ebe6b3d6876ffa27e7","title":"奉和李右相中书壁画山水","author":"孙逖","dynasty":"唐","verses":["庙堂多暇日，山水契中情。","欲写高深趣，还因藻绘成。","九江临户牖，三峡绕檐楹。","花柳穷年发，烟云逐意生。","能令万里近，不觉四时行。","气染荀香馥，光含乐镜清。","咏歌齐出处，图画表冲盈。","自保千年遇，何论八载荣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e3cb24d4-7cc5-47af-bcc5-1cfb41c03f3d","tags":[]},{"id":"poem-83227098cd95e560fe1f62bc","title":"君不见简苏徯","author":"杜甫","dynasty":"唐","verses":["君不见道边废弃池，君不见前者摧折桐。","百年死树中琴瑟，一斛旧水藏蛟龙。","丈夫盖棺事始定，君今幸未成老翁。","何恨顦顇在山中，深山穷谷不可处，霹雳魍魉兼狂风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-4cfeb483-2cfb-4f3e-8ed1-059eaccdd260","tags":[]},{"id":"poem-83231689a4a5f22474e2a83f","title":"春恨三首 一","author":"钱珝","dynasty":"唐","verses":["负罪将军在北朝，秦淮芳草绿迢迢。","高台爱妾魂销尽，始得丘迟为一招。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-30a8471a-2b0f-482d-80b6-7606855a84fc","tags":[]},{"id":"poem-832446f2f06f2a429ae7bc18","title":"奉赠韦左丞二十二韵","author":"杜甫","dynasty":"唐","verses":["纨袴不饿死，儒冠多误身。","丈人试静听，贱子请具陈。","甫昔少年日，早充观国宾。","读书破万卷，下笔如有神。","赋料扬雄敌，诗看子建亲。","李邕求识面，王翰愿卜邻。","自谓颇挺出，立登要路津。","致君尧舜上，再使风俗淳。","此意竟萧条，行歌非隐沦。","骑驴三十载，旅食京华春。","朝扣富儿门，暮随肥马尘。","残杯与冷炙，到处潜悲辛。","主上顷见征，歘然欲求伸。","青冥却垂翅，蹭蹬无纵鳞。","甚媿丈人厚，甚知丈人真。","每于百僚上，猥诵佳句新。","窃效贡公喜，难甘原宪贫。","焉能心怏怏，秪是走踆踆。","今欲东入海，即将西去秦。","尚怜终南山，回首清渭滨。","常拟报一饭，况怀辞大臣。","白鸥没浩荡，万里谁能驯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-bce77cf0-244d-435a-8a25-8d28a83bc4b9","tags":["终南山","社交","读书","壮志"]},{"id":"poem-83253c4a1979cbce31345058","title":"早起","author":"王十朋","dynasty":"宋","verses":["老欲投闲尚未成，胶胶扰扰厌余生。","方成枕上游仙梦，忽听窗前唤起声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f1f56fb7-6e0e-458c-bfa0-e9a7c3be1ee0","tags":[]},{"id":"poem-83310d0b15be6f67b10e629e","title":"七谏·自悲","author":"东方朔","dynasty":"汉","verses":["居愁懃其谁告兮，独永思而忧悲。","内自省而不惭兮，操愈坚而不衰。","隐三年而无决兮，岁忽忽其若颓。","怜余身不足以卒意兮，冀一见而复归。","哀人事之不幸兮，属天命而委之咸池。","身被疾而不闲兮，心沸热其若汤。","冰炭不可以相并兮，吾固知乎命之不长。","哀独苦死之无乐兮，惜予年之未央。","悲不反余之所居兮，恨离予之故乡。","鸟兽惊而失群兮，犹高飞而哀鸣。","狐死必首丘兮，夫人孰能不反其真情？","故人疏而日忘兮，新人近而俞好。","莫能行于杳冥兮，孰能施于无报？","苦众人之皆然兮，乘回风而远游。","凌恒山其若陋兮，聊愉娱以忘忧。","悲虚言之无实兮，苦众口之铄金。","过故乡而一顾兮，泣歔欷而沾衿。","厌白玉以为面兮，怀琬琰以为心。","邪气入而感内兮，施玉色而外淫。","何青云之流澜兮，微霜降之蒙蒙。","徐风至而徘徊兮，疾风过之汤汤。","闻南籓乐而欲往兮，至会稽而且止。","见韩众而宿之兮，问天道之所在？","借浮云以送予兮，载雌霓而为旌。","驾青龙以驰骛兮，班衍衍之冥冥。","忽容容其安之兮，超慌忽其焉如？","苦众人之难信兮，愿离群而远举。","登峦山而远望兮，好桂树之冬荣。","观天火之炎炀兮，听大壑之波声。","引八维以自道兮，含沆瀣以长生。","居不乐以时思兮，食草木之秋实。","饮菌若之朝露兮，构桂木而为室。","杂橘柚以为囿兮，列新夷与椒桢。","鹍鹤孤而夜号兮，哀居者之诚贞。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-34","tags":[]},{"id":"poem-8332ead601d857b2ce072635","title":"小重山·正是神京烂熳时","author":"和凝","dynasty":"五代","verses":["正是神京烂熳时，群仙初折得，郄诜枝。","乌犀白纻最相宜，精神出，御陌袖鞭垂。","柳色展愁眉，管弦分响亮，探花期。","光阴占断曲江池，新榜上，名姓彻丹墀。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-14","tags":[]},{"id":"poem-833378fcda3f9adf2f3e199b","title":"偈颂 六","author":"文偃","dynasty":"唐","verses":["丱岁依山人事稀，松下相逢话道奇。","锋前一句超调御，拟问如何历劫违。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-e78ec9c3-dc47-4616-9091-19791ad15777","tags":[]},{"id":"poem-8334814d0631b904565ee3b9","title":"喜迁莺·人汹汹","author":"韦庄","dynasty":"五代","verses":["人汹汹，鼓冬冬，襟袖五更风。","大罗天上月朦胧，骑马上虚空。","香满衣，云满路，鸾凤绕身飞舞。","霓旌绛节一群群，引见玉华君。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-12","tags":[]},{"id":"poem-833a768ff53c194ef1ad41a1","title":"绝句","author":"僧志安","dynasty":"宋","verses":["古木阴中系短篷，杖藜扶我过桥东。","沾衣欲湿杏花雨，吹面不寒杨柳风。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-絕句","tags":[]},{"id":"poem-833b736bf5e4d5119dbf431f","title":"酬李元叔察院见寄","author":"綦崇礼","dynasty":"宋","verses":["书到山中手自披，炎凉不改似君稀。","术穷五技缘何事，巢穏一枝聊可依。","扫迹径须休去好，冥心深觉向来非。","缓赓清唱缄题罢，却对松窗静掩扉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-df710afd-08e7-4f77-aa0c-2071d303215a","tags":[]},{"id":"poem-8341152f002147bc912b0d33","title":"石上丛竹","author":"释居简","dynasty":"宋","verses":["斗石森微干，杯泓托茂林。","不多犹绝俗，虽小亦虚心。","风噎纤纤玉，蟾低琐琐金。","胸中渺千亩，尺许对曾阴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-fdc885ee-bb87-4201-9930-2846c2ae45fb","tags":[]},{"id":"poem-834c2e88","title":"饮酒·其五","author":"陶渊明","dynasty":"晋","verses":["结庐在人境，而无车马喧。","问君何能尔？心远地自偏。","采菊东篱下，悠然见南山。","山气日夕佳，飞鸟相与还。","此中有真意，欲辨已忘言。"],"enabled":true,"collection":"历代名篇","source":"《陶渊明集》诗《饮酒二十首》其五。","tags":["田园","隐逸"]},{"id":"poem-834d08446b56596bd564f2e0","title":"宫词  其一八","author":"张公庠","dynasty":"宋","verses":["池北池南柳对黄，翠华游幸昼初长。","宫娥从驾知多少，十里朱轮半日香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8bd2eaac-fe90-4ade-a563-773ac2327a41","tags":[]},{"id":"poem-8357b394e7b4f0897bc9fbe5","title":"醉扶归","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦上)好苦切甘生受，只得到此且藏羞。","奴与哥哥有甚冤仇，只得慌忙便走，裙儿破忙把饭来兜。","(合)泪湿透衣衫袖。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8874","tags":[]},{"id":"poem-8364b15104d9a878eb2a17e5","title":"点绛唇·几日无书","author":"黄庭坚","dynasty":"宋","verses":["几日无书，举头欲问西来燕。","世情梦幻。","复作如斯观。","自叹人生，分合常相半。","戎虽远。","念中相见。","不托鱼和雁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-797","tags":[]},{"id":"poem-83651ac1560a1a5560211021","title":"早春池亭独游三首 三","author":"刘象","dynasty":"唐","verses":["一瓢欢自足，一日兴偏多。","幽意人先赏，疎丛蝶未过。","知音新句苦，窥沼醉颜酡。","万虑从相拟，今朝欲奈何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-42037650-82e1-41bf-9242-4f15afa08db2","tags":[]},{"id":"poem-836fd4aefba818f69385861d","title":"赠道者","author":"项斯","dynasty":"唐","verses":["晏来知养气，度日语时稀。","到处留丹井，终寒不絮衣。","病乡多惠药，鬼俗有符威。","自说身轻健，今年数梦飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1f3c63ce-c129-4339-b35b-9f58b7f68b8c","tags":[]},{"id":"poem-837324b6411cb4b7152900db","title":"除夜访杨此斋  其二","author":"王柏","dynasty":"宋","verses":["一别癯仙已八年，伶俜鹤骨尚弹冠。","相逢逆旅欢然处，各著精神子细看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-e8959609-c183-4212-9d5e-35da88d8c7cf","tags":[]},{"id":"poem-837c59bc7bbef878820ee483","title":"台州郡治十二诗太守尤延之命赋 玉霄亭","author":"林宪","dynasty":"宋","verses":["蜿蜒龙顾山，霄汉在人境。","古亭压虚无，云气倒天景。","天澄碧芙蕖，一叶一亭影。","凝然千叶上，有客动深省。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-e378ebe2-513b-4cac-81a9-9a5a265093b4","tags":[]},{"id":"poem-8382e0ea57c4343f7a11d812","title":"夜下湘中","author":"马戴","dynasty":"唐","verses":["洞庭人夜别，孤棹下湘中。","露洗寒山遍，波摇楚月空。","密林飞暗狖，广泽发鸣鸿。","行值扬帆者，江分又不同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-20ec62d2-e652-45e4-a44d-d9a5b7266a2e","tags":["洞庭湖"]},{"id":"poem-8388fdb853459cb6e30acb02","title":"双翠羽·小园曲径","author":"赵鼎","dynasty":"宋","verses":["小园曲径，度疏林深处，幽兰微馥。","竹坞无人双翠羽，飞触珊珊寒玉。","更欲题诗，晚来孤兴，却恐伤幽独。","不如花下，一尊芳酒相属。","慨念故国风流，杨花春梦短，黄粱初熟。","卷白千觞须劝我，洗此胸中荣辱。","醉揖南山，一声清啸，休把离骚读。","迟留归去，月明犹挂乔木。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-954","tags":[]},{"id":"poem-839253c06b7628b312d75890","title":"·","author":"程杰","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d081a00f-aa81-4fd7-af7e-6e4f6dd3609e","tags":[]},{"id":"poem-8394944e8974813eb9aea4af","title":"忆多娇","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(末)心痛惜，情惨戚，将身赴江学抱石。","可怜夫妇鸾凤拆，(合)即日登程，即日登程，渺渺音容远隔。","(末)老安人，不须啼哭，趱行前去。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8240","tags":[]},{"id":"poem-8396c1fd5614fe2335026858","title":"喜迁莺·晓光催角","author":"刘一止","dynasty":"宋","verses":["晓光催角。","听宿鸟未惊，邻鸡先觉。","迤逦烟村，马嘶人起，残月尚穿林薄。","泪痕带霜微凝，酒力冲寒犹弱。","叹倦客、悄不禁，重染风尘京洛。","追念，人别后，心事万重，难觅孤鸿托。","翠幌娇深，曲屏香暖，争念岁寒飘泊。","怨月恨花烦恼，不是不曾经著。","这情味，望一成消减，新来还恶。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-265","tags":["宋词三百首"]},{"id":"poem-8396fb47f11d9f5db3dc4672","title":"浣溪沙·一半残阳下小楼","author":"纳兰性德","dynasty":"清","verses":["一半残阳下小楼，朱帘斜控软金钩。","倚阑无绪不能愁。","有个盈盈骑马过，薄妆浅黛亦风流。","见人羞涩却回头。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-26","tags":[]},{"id":"poem-839bdc1ead0a4924b75d9c0b","title":"同马太守听九思法师讲金刚经","author":"高适","dynasty":"唐","verses":["吾师晋阳宝，杰出山河最。","途经世谛间，心到空王外。","鸣钟山虎伏，说法天龙会。","了义同建瓴，梵法若吹籁。","深知亿劫苦，善喻恒沙大。","舍施割肌肤，攀缘去亲爱。","招提何清净，良牧驻轻盖。","露冕众香中，临人觉苑内。","心持佛印久，标割魔军退。","愿开初地因，永奉弥天对。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b39ad3db-8f27-43c9-a11d-9b16e5259431","tags":[]},{"id":"poem-83a570d6b17d9622ebbee618","title":"郊庙歌辞 祀圜丘乐章 肃和","author":"褚亮","dynasty":"唐","verses":["闿阳播气，甄曜垂明。","有赫圜宰，深仁曲成。","日丽苍璧，烟开紫营。","聿遵干享，式降鸿祯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-cba1afc6-35ad-43bd-a997-2eb2fb1d2105","tags":[]},{"id":"poem-83aa974a9de6175eaaa1af53","title":"寄呈东甽先生曹侍郎","author":"宋伯仁","dynasty":"宋","verses":["芝书催觐已多时，底事归班似嬾归。","诸老正缘无定说，先生只得暗知机。","柳花樽俎春千点，竹屋云山绿四围。","东甽东边行乐遍，不妨款曲上黄扉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-ccd0ff11-db36-4c2d-8662-6c69d1b5a172","tags":[]},{"id":"poem-83b2bdbd001dad75b9ec0396","title":"山居诗  其五八","author":"释延寿","dynasty":"宋","verses":["养性摅情不记年，免寻云水更参禅。","有心用处还应错，无意看时却宛然。","析法尚嫌灰断果，烧丹堪愍地行仙。","欲知此理谁人会，水自朝东月自圆。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-2b0641af-63b7-4b29-a7c2-737f29b1c673","tags":[]},{"id":"poem-83c4344ba06e60a14c5396f1","title":"天仙子·洞口春红飞蔌蔌","author":"和凝","dynasty":"五代","verses":["洞口春红飞蔌蔌，仙子含愁眉黛绿。","阮郎何事不归来，懒烧金，慵篆玉。","流水桃花空断续。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-25","tags":[]},{"id":"poem-83c5c5372e7c456a8270b48e","title":"郊庙歌辞 享龙池乐章 第三章","author":"沈佺期","dynasty":"唐","verses":["龙池跃龙龙已飞，龙德[光]天天不违。","池开天汉分黄道，龙向天门入紫微。","邸第楼台多气色，君王凫雁有光辉。","为报寰中百川水，来朝此地莫东归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d291f734-2ec4-4eed-9c5e-8f14c4d11921","tags":[]},{"id":"poem-83c71bc72f2eacc874ec344c","title":"利州南渡","author":"温庭筠","dynasty":"唐","verses":["澹然空水对斜晖，曲岛苍茫接翠微。","波上马嘶看櫂去，柳边人歇待船归。","数丛沙草群鸥散，万顷江田一鹭飞。","谁解乘舟寻范蠡，五湖烟水独忘机。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ac97d42b-8fef-42c9-829f-baafe89b4cdc","tags":["唐诗三百首","七言律诗","抒怀","渡江","山水"]},{"id":"poem-83d44bd86fa5f7517478e2c9","title":"玉蘂花","author":"何兆","dynasty":"唐","verses":["羽车潜下玉龟山，尘世何缘覩蕣颜。","惟有多情天上雪，好风吹上绿云鬟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-db497d72-aefd-4639-88d1-dc93999b1de4","tags":[]},{"id":"poem-83d9aeab9d7d86fb5013e67b","title":"似娘儿","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外上］一女貌天然，缘分浅。","亲事迁延。","愿天早与人方便，丝萝共结，蒹葭可倚，桑梓相联。","\"男子生而愿为之有室，女子生而愿为之有家。","\"老夫昨央将仕王宅议亲，回来便知端的。","［末上］伏托荆钗成好事，何须红叶作良媒。","昨蒙贡元央我王宅议亲，不免回复。","有人么？［外］将仕，有劳动问，亲事如何？［未］老夫初到王宅，说起亲事，王老安人再三推辞。","已后将尊言说明，谗得允从。","［外］将何物为聘？［末］聘物虽有，只是轻微，将不出。","［外］老夫有言在先，不拘轻重，只要成其姻事。","［末］聘物在此，请收。","［外］好罕物。","昔日汉粱鸿聘孟光荆钗，至今遗下，岂不是达古之家？老安人那里？［净争上］\"姻缘本是前生定，曾向蟠桃会里来。","\"那个在此？［外］是将仕。","［净］不是来说我儿亲事么？［外］正是。","［净］李成看茶来。","将仕公，外日多蒙厚礼，我说李成去请将仕公来吃些寿面，说你不在家；一钵头面，放了三日，把与狗吃了。","［外、末］这什么说话？［净］敢问将仕，说我女儿亲事怎么了？［末、外］亲事已成了。","［净］既成了，几时下盒子？［末、外］就是今日。","［净］今日教我怎么安排得酒与来人吃？［末］都是干折，袖里来，袖里去。","［净］看鸡鹅污屎，坏了衣服。","［末］不是这个干折。","［净］小厮讨天平来。","［外］要天平做什么？［净］要他兑银子。","［外］银子希什么罕？［净］银子不希罕，什么希罕？［外］一股荆钗，只怕你不晓得。","［净］你拿来我看。","多少年纪，不晓得这是什么东西。","闻又不香，拿在手又不重，待我磨一磨。","［外］这是宝贝，擦不得的。","［净］人到禁擦，他到不禁擦。","［外、末］什么说话？［净］这味头簪子，一分银子买了十根，讨得十个媳妇。","［外］不要多说。","［净］我晓得。","当初汉梁鸿仗他讨了个娘子，如今又将来讨我女儿，是二婚人了。","［末］休得取笑。","［净］你便说何人置造，甚人遗下的？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8067","tags":[]},{"id":"poem-83da9254ae58fc78d169b869","title":"一斛珠·晓妆初过","author":"李煜","dynasty":"五代","verses":["晓妆初过，沈檀轻注些儿个。","向人微露丁香颗。","一曲清歌，暂引樱桃破。","罗袖裛残殷色可，杯深旋被香醪涴。","绣床斜凭娇无那。","烂嚼红茸，笑向檀郎唾。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-6","tags":[]},{"id":"poem-83db58e102b13ff736f8d455","title":"深春  其一","author":"王镃","dynasty":"宋","verses":["夹泥花上燕巢边，翠箔桑空蚕又眠。","天气才晴风候别，坐看盆藕出双钱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-46e4c445-b887-4f77-8686-773ba41f7adf","tags":[]},{"id":"poem-83eb8a27fa1ce46a3ba90b40","title":"女冠子·星高月午","author":"李珣","dynasty":"五代","verses":["星高月午，丹桂青松深处。","醮坛开，金磬敲清露，珠幢立翠苔。","步虚声缥缈，想象思徘徊。","晓天归去路，指蓬莱。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-35","tags":[]},{"id":"poem-83f0f6aa6b153c8d7e9138a6","title":"旅兴","author":"王琮","dynasty":"宋","verses":["经年客食向京华，懒对春风祇忆家。","觉道近来全俗了，略无一语及梅花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1c2623fe-8007-46b8-aa1c-c0a3f35be072","tags":[]},{"id":"poem-83f5f38c0c815cb827b83c59","title":"权舆","author":"佚名","dynasty":"先秦","verses":["于我乎，夏屋渠渠，今也每食无余。于嗟乎，不承权舆！","于我乎，每食四簋，今也每食不饱。于嗟乎，不承权舆！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-134","tags":[]},{"id":"poem-840bd60d09fbe224f0b74d70","title":"游仙二首 一","author":"司空图","dynasty":"唐","verses":["蛾眉新画觉婵娟，鬬走将花阿母边。","仙曲教成慵不理，玉阶相簇打金钱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-75af1049-35a3-42ae-bffd-90089bf3ef27","tags":[]},{"id":"poem-8413b8287804e099f25d9923","title":"留别南溪二首 一","author":"李渤","dynasty":"唐","verses":["常叹春泉去不回，我今此去更难来。","欲知别后留情处，手种岩花次第开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-8f00a135-544d-4360-9988-a8bea3fe943a","tags":[]},{"id":"poem-8420dc72360afad809a89674","title":"水龙吟·夜来风雨匆匆","author":"程垓","dynasty":"宋","verses":["夜来风雨匆匆，故园定是花无几。","愁多愁极，等闲孤负，一年芳意。","柳困花慵，杏青梅小，对人容易。","算好春长在，好花长见，元只是、人憔悴。","回首池南旧事。","恨星星、不堪重记。","如今但有，看花老眼，伤时清泪。","不怕逢花瘦，只愁怕、老来风味。","待繁红乱处，留云借月，也须拼醉。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-218","tags":["宋词三百首"]},{"id":"poem-842b475468d647a35e34b23b","title":"边上作三首 一","author":"贯休","dynasty":"唐","verses":["山无绿兮水无清，风既毒兮沙亦腥。","胡儿走马疾飞鸟，联翩射落云中声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4135e905-70cf-4329-9c96-d95134949a77","tags":[]},{"id":"poem-8436b4f56cc0f63dedb340a8","title":"韩文公见大颠","author":"释了惠","dynasty":"宋","verses":["事繁求省要，省要事频繁。","纵得三平老，文公只姓韩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-18d0453c-94f6-4533-bc37-0a8f77853694","tags":[]},{"id":"poem-8441a5c646edcd5e044951c3","title":"赠同住归寂颂（一作《归寂吟赠同住》）","author":"智闲","dynasty":"唐","verses":["同住道人七十余，共辞城郭乐山居。","身如寒木心芽（一作「牙」）绝，不话唐言休梵书。","心期尽处身虽丧，如来弟子沙门样。","深信共崇钵塔成，巍巍置在青山嶂（一作「掌」）。","观夫参道不虚然，脱去形骸惎（一作「甚」）高上。","从来不说今朝事，暗里埋头隐玄畅。","不留踪迹异人间，深妙神光饱明亮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-ae0c98fc-0de3-4746-ab30-7754d315bad0","tags":[]},{"id":"poem-84464636e8592f1a35e18b45","title":"渔家傲·海角秋高风力骤","author":"李弥逊","dynasty":"宋","verses":["海角秋高风力骤。","楼台四面山容瘦。","季子貂裘寒欲透。","悬弧昼。","高歌棣萼聊卮酒。","且共追欢宽白首。","清闲赢得身长久。","世上功名翻覆手。","为君寿。","腰间要看悬金斗。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-50","tags":[]},{"id":"poem-844d40a31e7a452aa217ce16","title":"题武陵洞五首 一","author":"曹唐","dynasty":"唐","verses":["此生终使此身闲，不是春时且要还。","寄语桃花与流水，莫辞相送到人间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c4f1f2e0-ae1f-41ab-970f-9de7cf4d61a0","tags":[]},{"id":"poem-845325d992880dd2b286cc2f","title":"闻无相道人顺世五首 三","author":"贯休","dynasty":"唐","verses":["常思将道者，高论地炉傍。","迂谈无世味，夜深山木僵。","下山遭离乱，多病惟深藏。","一别三十年，烟水空茫茫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-db52ba9d-b7c0-4a0a-9b69-4d55c3d4f2f5","tags":[]},{"id":"poem-8466c99732495b5633ba8403","title":"沈醉东风","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外］我孩儿三生有缘，与才郎忝为姻眷。","今日赴春闹，程途遥远。","论盘费，尚忧轻鲜。","［旦］婆当暮年，父当老年，只愿我儿夫荣归故苑。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8134","tags":[]},{"id":"poem-8468930d715b2b30257097b2","title":"闲游","author":"张籍","dynasty":"唐","verses":["老身不计人间事，野寺秋晴每独过。","病眼校来犹断酒，却嫌行处菊花多。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e7818efd-615f-4df7-bd23-3cfefcba3cdc","tags":[]},{"id":"poem-8486506bc700676abbcd0e3a","title":"夜宿浙江","author":"孙逖","dynasty":"唐","verses":["扁舟夜入江潭泊，露白风高气萧索。","富春渚上潮未还，天姥岑边月初落。","烟水茫茫多苦辛，更闻江上越人吟。","洛阳城阙何时见，西北浮云朝暝深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-544ad2e6-3834-4f84-908c-5fcb06ee636d","tags":[]},{"id":"poem-8487748ca156dc6a96262a48","title":"寄孙冲主簿","author":"张籍","dynasty":"唐","verses":["低折沧州簿，无书整两春。","马从同事借，妻怕罢官贫。","道僻收闲药，诗高笑故人。","仍闻长吏奏，表乞锁厅频。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-415041a9-5162-4470-b063-74957cf056cb","tags":[]},{"id":"poem-8495469a8fa6aa423c14fadf","title":"次韵友人","author":"赵文","dynasty":"宋","verses":["相逢小坐芷花秋，绝胜扬鞭并与幽。","世上十年尘转海，人生万事博悬投。","当时对酒曾辞酒，今日言愁始欲愁。","何不倒囊来一醉，旧题重访酒边楼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-8cecb1ab-fbbe-4f3a-a51e-1cfbbf24331e","tags":[]},{"id":"poem-84964aa52aeec53060ee58ae","title":"奉和受图温洛应制","author":"牛凤及","dynasty":"唐","verses":["八神扶玉辇，六羽警瑶谿。","戒道伊川北，通津涧水西。","御图开洛匮，刻石与天齐。","瑞日波中上，仙禽雾里低。","微臣矫羽翮，抃舞接鸾鹥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e104cb68-869c-4afb-8af9-69902118d43e","tags":[]},{"id":"poem-8496c24916db33128fb979d4","title":"闻新蝉寄桂雍","author":"贯休","dynasty":"唐","verses":["新蝉终夜呌，嘒嘒隔溪𣸣。","杜宇仍相杂，故人闻不闻。","卷帘花动月，冥目砌生云。","终共谢时去，西山鸾鹤群。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ebe9157b-aa85-4210-b319-51c686e3c00f","tags":[]},{"id":"poem-8496e445836c4b2019bff2bf","title":"识全","author":"释居简","dynasty":"宋","verses":["占得沙边柳外春，更专吟啸管阴晴。","延祥观后茅茨老，月旦工夫子细评。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-45405c03-1b21-4a87-920e-3af34c9e46a1","tags":[]},{"id":"poem-84a1925d841bb6e9371725d3","title":"与郑锡游春","author":"李端","dynasty":"唐","verses":["东门垂柳长，回首独心伤。","日煖临芳草，天晴忆故乡。","暎花鸎上下，过水蝶飞扬。","借问同行客，今朝泪几行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-37f4077e-4ef3-4815-bcf9-e8d0e177799d","tags":[]},{"id":"poem-84a9ecd47a909c764f737dc3","title":"句  其四","author":"林宪","dynasty":"宋","verses":["绝无声色动凡情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-2d816679-bde2-4bbc-8e5a-fee500f7d5e8","tags":[]},{"id":"poem-84aa993f31f679caadd52123","title":"考槃","author":"佚名","dynasty":"先秦","verses":["考槃在涧，硕人之宽。独寐寤言，永矢弗谖。","考槃在阿，硕人之薖。独寐寤歌，永矢弗过。","考槃在六，硕人之轴。独寐寤宿，永矢弗告。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-55","tags":[]},{"id":"poem-84ab01a41c30534b0ca9e9b4","title":"和友人喜相遇十首 五","author":"李咸用","dynasty":"唐","verses":["闲吟闲坐道相应，远想南华亦自矜。","抛掷家乡轻似梦，寻常心地冷于僧。","和羹使用非胥靡，忆鲙言词小季鹰。","唯仗十篇金玉韵，此中高旨莫阶升。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0d5a26cf-e3e6-48e9-9167-8ae2e35ca957","tags":[]},{"id":"poem-84b3344201e3844e74435f1a","title":"偈颂（幷序○序为南岳齐己撰） 八十二","author":"居遁","dynasty":"唐","verses":["体得无生意，朝朝近古人。","若也更不会，虽乐苦临身。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-e3c6aa26-7557-4f68-959a-da6e0c04371f","tags":["衡山"]},{"id":"poem-84b3a9dd146de189dc22816a","title":"句","author":"徐安贞","dynasty":"唐","verses":["暮雨衣犹湿，春风帆正开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-250a51c8-4f9f-4591-8a80-2f9936a6df35","tags":[]},{"id":"poem-84b6de8ccf4f3e96513a41db","title":"送禅师宗极归玉峰","author":"栖白","dynasty":"唐","verses":["背郭去归宿，头陀意颇浓。","鹤争栖远树，猨鬬上孤峰。","夜戍经霜月，秋城过雨钟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-38171e7f-158a-43d6-bf6e-be26927a569b","tags":[]},{"id":"poem-84b77b7388bf234a41b96df5","title":"伊川晚眺","author":"李德裕","dynasty":"唐","verses":["桑叶初黄梨叶红，伊川落日尽无风。","汉储何假终南客，甪里先生在谷中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-383eda54-11ce-47da-be4a-c79a1dce423a","tags":[]},{"id":"poem-84b7e094cd1d278115c769f7","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(生)提着心肠惨凄，不由人忍不住泪珠流颗，但有死别生离，那烦恼似天来大。","(小生)缘何？莫非他弃旧怜新，从了别个？(生)不是。","(小生)多应是疾病亡，遭非祸。","(生)不是。","你道为甚么？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3045","tags":[]},{"id":"poem-84b947e095919e7da488f1bb","title":"题定武兰亭古本","author":"米芾","dynasty":"宋","verses":["翰墨风流冠古今，鹅池谁不赏山阴。","此书虽向昭陵朽，刻石犹能易黄金。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-8c59b478-b5a4-4e57-b428-be88d607b08b","tags":[]},{"id":"poem-84bf10ce580822295b324136","title":"虾蟆序","author":"施惠《幽闺记》","dynasty":"元","verses":["(生)摧挫。","艰共险，愁和闷，要躲怎躲，到如今尚有平地风波！(小生)惊愕。","焰腾腾心上火，是谁人道与我？(生)你道如何，爱富嫌贫，岳丈倚强凌弱。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3046","tags":[]},{"id":"poem-84d44c6a59482b149072eac9","title":"减字木兰花·杨花飘尽","author":"康与之","dynasty":"宋","verses":["杨花飘尽。","云压绿阴风乍定。","帘幕闲垂。","弄语千般燕子飞。","小楼深静。","睡起残妆犹未整。","梦不成归。","泪滴斑斑金缕衣。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-323","tags":[]},{"id":"poem-84d65906c7b43fae0dc0258b","title":"好事近·飞盖满南园","author":"毛并","dynasty":"宋","verses":["飞盖满南园，想见八仙遥集。","几树海棠开遍，正新晴天色。","休辞一醉任扶还，衣上酒痕湿。","便恐岁华催去，听秋虫相泣。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-612","tags":[]},{"id":"poem-84e878bcdd9a8d49167aef86","title":"定之方中","author":"佚名","dynasty":"先秦","verses":["定之方中，作于楚宫。揆之以日，作于楚室。树之榛栗，椅桐梓漆，爰伐琴桑。","升彼虚矣，以望楚矣。望楚与堂，景山与京。降观于桑，卜云其吉，终然允臧。","灵雨既零，命彼倌人，星言夙驾，说于桑田。匪直也人，秉心塞渊，騋牝三千。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-49","tags":[]},{"id":"poem-84ebc009a0bdd1dddf2b8833","title":"菩萨蛮·玉绳斜转疑清晓","author":"纳兰性德","dynasty":"清","verses":["玉绳斜转疑清晓，凄凄月白渔阳道。","星影漾寒沙，微茫织浪花。","金笳鸣故垒，唤起人难睡。","无数紫鸳鸯，共嫌今夜凉。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-184","tags":[]},{"id":"poem-84f25acf0b34c750ba4668bd","title":"横吹曲辞 出塞曲 二","author":"于鹄","dynasty":"唐","verses":["单于骄爱猎，放火到军城。","待月调新弩，防秋置远营。","空山朱戟影，寒碛铁衣声。","逢著降胡说，阴山有伏兵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-db605400-358d-4cb3-93af-2b6316ae9620","tags":[]},{"id":"poem-850ea6f49e72e14627747815","title":"太真入宫图二首  其一","author":"赵文","dynasty":"宋","verses":["未舞霓裳宝髻斜，流苏帐里再盘鸦。","君王细看春风面，终是香云减一些。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-25542757-f725-402e-b82e-2fb84453bf3e","tags":[]},{"id":"poem-85198c1943e6ce121b13a17f","title":"张子真杨政光吴德夫追路湘源赋此以别","author":"张栻","dynasty":"宋","verses":["驱车出严关，触热归路长。","一雨群物苏，吾行亦清凉。","漓水自南去，湘流正洋洋。","眷言二三友，跋马勤送将。","萧然短长亭，每语夜未央。","张子名家驹，千里方腾骧。","杨郎岭中彦，而能歛锋铓。","延陵旧所熟，气味固难忘。","向来幕府游，三秀丽斋房。","居然出别语，分袂楚粤乡。","人生会有别，勿悲参与商。","独有赠言意，临岐更平章。","风俗易移人，宦途剧羊肠。","千钧有不守，决去飞鸟翔。","要当勉自持，诗书作金汤。","他年相会处，刮目看增光。","为谢桂父老，无泽留一方。","惟余石间字，时与洗苔苍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-d643b84d-3c78-43dd-8f54-767614e29cd0","tags":[]},{"id":"poem-851c3c90df10cc6df99afb72","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)休为我相思损天常，紧攻书，临选场。","(生)我不道再，我不道再娶重婚，你焉肯终身守孀？(合)苦别离。","愁断肠；两分离，愁断畅。","(外)六儿。","快扯上马去。","(丑扯科)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3015","tags":[]},{"id":"poem-85239bf8b6d8606380ccc9f0","title":"偈三首  其一","author":"释祖瑃","dynasty":"宋","verses":["道无定乱，法离见知。","言句相投，都无定义。","自古龙门无宿客，至今鸟道绝行踪。","欲会个中端的意，火里蝍蟟吞大虫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-1b0203b0-75b1-4553-a713-3a3df3285236","tags":[]},{"id":"poem-8526f18c3ffad2145c92ee17","title":"醉垂鞭·双蝶绣罗裙","author":"张先","dynasty":"宋","verses":["双蝶绣罗裙。","东池宴。","初相见。","朱粉不深匀。","闲花淡淡春。","细看诸处好。","人人道。","柳腰身。","昨日乱山昏。","来时衣上云。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-154","tags":["宋词三百首"]},{"id":"poem-852d2fc34e72983df69aef24","title":"谢白乐天招","author":"韬光","dynasty":"唐","verses":["山僧野性好林泉，每向岩阿倚石眠。","不解栽松陪玉勒，惟能引水种金莲。","白云乍可来青嶂，明月难教下碧天。","城市不能飞锡去，恐妨莺啭翠楼前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d337e5a0-0265-4747-972f-d41a99d83489","tags":[]},{"id":"poem-85329135b7c1ec55e39de95b","title":"江行无题一百首 九十四","author":"钱珝","dynasty":"唐","verses":["愿饮西江水，那吟北渚愁。","莫教留滞迹，远比蔡昭侯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-005f6c5a-a14c-4396-a092-bf8d0bcf478b","tags":["长江"]},{"id":"poem-853a9d2f91c6351fb8133801","title":"瑞鹧鸪·吴会风流","author":"柳永","dynasty":"宋","verses":["吴会风流。","人烟好，高下水际山头。","瑶台绛阙，依约蓬丘。","万井千闾富庶，雄压十三州。","触处青娥画舸，红粉朱楼。","方面委元侯。","致讼简时丰，继日欢游。","襦温裤暖，已扇民讴。","旦暮锋车命驾，重整济川舟。","当恁时，沙堤路稳，归去难留。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-230","tags":[]},{"id":"poem-853b50799546d0e783650d95","title":"喜逢妻弟郑损因送入京","author":"崔峒","dynasty":"唐","verses":["乱后自江城，相逢喜复惊。","为经多载别，欲问小时名。","对酒悲前事，论文畏后生。","遥知盈卷轴，纸贵在江城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-580aa9a1-188d-4ba7-abae-7cdf6e2ac289","tags":[]},{"id":"poem-85446b3c49e137bd9906ccc2","title":"雨后山水入潮江方岩索赋","author":"释居简","dynasty":"宋","verses":["湍雪投江只得浑，观澜未了复消魂。","不知从此随流去，清白何时得反元。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-64e3e3bb-8eb1-4af0-9d45-20bfa21a07b5","tags":[]},{"id":"poem-8559a177201211b8972d5784","title":"偈颂（幷序○序为南岳齐己撰） 十五","author":"居遁","dynasty":"唐","verses":["劫火曾将无气吹，不劳心力当时萎。","人天不见风尘起，怖息无招各自归。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-43c986ee-1be1-41f1-a2ab-39e2f5824040","tags":["衡山"]},{"id":"poem-85609183e4915d2f78f82180","title":"寓天台水南四首  其一","author":"林宪","dynasty":"宋","verses":["小雨凄暮春，入夜寒更作。","泠泠竹间风，振我衣袂薄。","野田鸣流泉，密树纷翠幄。","蹑屐徐我行，长怀付寥廓。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-43ad5ead-7254-477f-b143-658c161cafd9","tags":[]},{"id":"poem-85646d621a709f6b9e5655cc","title":"题刘炼师归山","author":"唐求","dynasty":"唐","verses":["风急云轻鹤背寒，洞天谁道却归难。","千山万水瀛洲路，何处烟飞是醮坛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c87c1927-03e4-4104-97e5-f5fb54de3345","tags":[]},{"id":"poem-8564ff0f73e2af1b5d479ae2","title":"九日","author":"蔡孚","dynasty":"唐","verses":["九日重阳节，开门有菊花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0dfd7481-431a-4f4c-87e3-f22f8faee2a9","tags":[]},{"id":"poem-8565a42f15e1e493fe36fa8f","title":"滚绣球","author":"杨景贤","dynasty":"元","verses":["这扇子六丁神巧铸成，五道神细打磨，阎浮间并无二个，上秤称一千斤犹有余多。","管他二十四气风，吹灭八十一洞火，火焰山神见咱也胆破，恼着我呵登时间便起干戈。","我且着扇扇翻地狱门前树，卷起天河水波，我是第一洞妖魔。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2347","tags":[]},{"id":"poem-85818d7e5ca6e5bf8aac1e85","title":"杂曲歌辞 丽人行","author":"杜甫","dynasty":"唐","verses":["三月三日天气新，长安水边多丽人。","态浓意远淑且真，肌理细腻骨肉匀。","绣罗衣裳照暮春，蹙金孔雀银麒麟。","头上何所有？翠微㔩叶垂鬓唇。","背后何所见？珠压腰衱稳称身。","就中云幕椒房亲，赐名大国虢与秦。","紫駞之峰出翠釜，水晶之盘行素鳞。","犀筯厌饫久未下，鸾刀缕切空纷纶。","黄门飞鞚不动尘，御厨丝络送八珍。","箫鼓哀吟感鬼神，宾从杂遝实要津。","后来鞍马何逡巡，当轩下马入锦茵。","杨花雪落覆白苹，青鸟飞去衔红巾。","炙手可热势绝伦，慎莫近前丞相嗔。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-aaae5882-9b74-4b45-9bb5-9f773a721119","tags":["唐诗三百首","杂曲歌辞","乐府","讽刺","咏叹"]},{"id":"poem-85874f7dd4224cfd437cac9f","title":"夜送赵纵","author":"杨炯","dynasty":"唐","verses":["赵氏连城璧，由来天下传。","送君还旧府，明月满前川。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-夜送趙縱","tags":[]},{"id":"poem-8589fc2d2a7738daf0d6a0f6","title":"绍圣二年八月十八日观潮于浙江亭书","author":"米芾","dynasty":"宋","verses":["怒势豪声迸海门，州人传是子胥魂。","天排云阵千雷震，地卷银山万马奔。","高与月轮参朔望，信如壶漏报朝昏。","吴争越战成何事，一曲渔歌过远村。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-51bb7de5-61c1-47d1-886c-532fd97f7273","tags":["钱塘江"]},{"id":"poem-85920d7e28617465a92c5d6d","title":"晚景","author":"子兰","dynasty":"唐","verses":["池荷衰飒菊芬芳，策杖吟诗上草堂。","满目暮云风卷尽，郡楼寒角数声长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1a86d2a6-234b-465a-b109-c96b6c837e5a","tags":[]},{"id":"poem-85963232351fe1db71f367ce","title":"横吹曲辞 折杨柳","author":"李端","dynasty":"唐","verses":["东城攀柳叶，柳叶低著草。","少壮莫轻年，轻年有人老。","柳发徧川岗，登高堪断肠。","雨烟轻漠漠，何树近君乡？","赠君折杨柳，颜色岂能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳伤君情。","突兀临荒渡，婆娑出旧营。","隋家两岸尽，陶宅五株平。","日暮偏愁望，春山有鸟声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5b2c85ac-3edd-43b7-aa6d-b32c31d01bd0","tags":[]},{"id":"poem-85a50b3ed48dc511963b713d","title":"自河西归山二首 二","author":"司空图","dynasty":"唐","verses":["水阔风惊去路危，孤舟欲上更迟迟。","鹤群长扰三珠树，不借人间一只骑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-819bc650-9daf-4dbb-9950-dafd26e7f2f1","tags":[]},{"id":"poem-85a745c1a235e15880aeccc3","title":"望江南·多少恨","author":"李煜","dynasty":"五代","verses":["多少恨，昨夜梦魂中。","还似旧时游上苑，车如流水马如龙。","花月正春风。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-10","tags":[]},{"id":"poem-85a93e791c0b97227f924866","title":"子衿","author":"佚名","dynasty":"先秦","verses":["青青子衿，悠悠我心。纵我不往，子宁不嗣音？","青青子佩，悠悠我思。纵我不往，子宁不来？","挑兮达兮，在城阙兮。一日不见，如三月兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-90","tags":[]},{"id":"poem-85a9fcf9d38b314b8594303a","title":"朝中措·郎官湖上探春回","author":"李祁","dynasty":"宋","verses":["郎官湖上探春回。","初见照江梅。","过尽竹溪流水，无人知道花开。","佳人何处，江南梦远，殊未归来。","唤取小丛教看，隔江烟雨楼台。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-604","tags":[]},{"id":"poem-85ba3aae0fce305ae36ebc31","title":"青玉案·东风夜放花千树","author":"辛弃疾","dynasty":"宋","verses":["东风夜放花千树。","更吹落、星如雨。","宝马雕车香满路。","凤箫声动，玉壶光转，一夜鱼龙舞。","蛾儿雪柳黄金缕。","笑语盈盈暗香去。","众里寻他千百度。","蓦然回首，那人却在，灯火阑珊处。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-214","tags":["宋词三百首"]},{"id":"poem-85ba8d865960e7b85d50d11d","title":"菩萨蛮·寄梁汾苕中","author":"纳兰性德","dynasty":"清","verses":["知君此际情萧索，黄芦苦竹孤舟泊。","烟白酒旗青，水村鱼市晴。","柁楼今夕梦，脉脉春寒送。","直过画眉桥，钱塘江上潮。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-186","tags":[]},{"id":"poem-85cd0d02106d6b02ba285caf","title":"咏史诗 汉江","author":"胡曾","dynasty":"唐","verses":["汉江一带碧流长，两岸春风起绿杨。","借问胶船何处没，欲停兰棹祀昭王。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-1b462661-1e9a-4410-a99b-0203bb4cfef6","tags":[]},{"id":"poem-85d873adf5af367b10db379d","title":"前腔换头","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["堪哀，萱室先摧。","叹妇仪姆训，未曾谙解。","蒙爹严命，从今怎敢不改！老姥姥，早晚望伊家将奴诲。","惜春，改前非休违背。","(合前)(净唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4966","tags":[]},{"id":"poem-85e005081cad5ecf31d078ed","title":"江城子·䴔䴖飞起郡城东","author":"牛峤","dynasty":"五代","verses":["䴔䴖飞起郡城东，碧江空，半滩风。","越王宫殿，苹叶藕花中。","帘卷水楼鱼浪起，千片雪，雨蒙蒙。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-25","tags":[]},{"id":"poem-85e1045c005a31d6344ccd32","title":"次韵徐秀才十首  其三","author":"陈造","dynasty":"宋","verses":["向来孟浩然，醉眼高宇宙。","清诗落京师，苏李欲束咮。","蔗陇槎头鳊，未觉黄金富。","纤钩饵虾蝇，但取浮阳嗅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-7ada2ea4-c26d-4235-b551-b9bdaa9dd91b","tags":[]},{"id":"poem-85f3c71b80ce4d23818a1616","title":"句  其七","author":"林迥","dynasty":"宋","verses":["汲水僧归林下寺。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-973a3789-f135-4ad5-b564-b1a7242c7016","tags":[]},{"id":"poem-85fe33459e22143c03534833","title":"荅韦先辈春雨后见寄","author":"刘得仁","dynasty":"唐","verses":["风散五更雨，鸟啼三月春。","轩窗透初日，砚席绝纤尘。","帝里峰头出，邻家树色新。","怜君高且静，有句寄闲人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-02de7d48-2092-43ac-9f42-b34c0f529353","tags":[]},{"id":"poem-860e5d6eef16106250ad790e","title":"天仙子·怅望前回梦里期","author":"韦庄","dynasty":"五代","verses":["怅望前回梦里期，看花不语苦寻思。","露桃花里小腰肢，眉眼细，鬓云垂，唯有多情宋玉知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-7","tags":[]},{"id":"poem-861694da998445e408adff3d","title":"江楼旧感","author":"赵嘏","dynasty":"唐","verses":["独上江楼思渺然，月光如水水如天。","同来望月人何处，风景依稀似去年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-244610b1-65f6-41fb-a29a-490e3a75d3ce","tags":[]},{"id":"poem-861da0cde3d9d781b506630a","title":"满庭芳·江草抽心","author":"李石","dynasty":"宋","verses":["江草抽心，江云弄碧，江波依旧东流。","别筵初散，行客上兰舟。","休唱阳关旧曲，青青柳、无限轻柔。","应争记，三年乐事，珠翠拥鳌头。","离愁。","知几许，花梢著雨，红泪难收。","看烟火吴天，万里悠悠。","一望珠宫绛阙，蓬莱路、应在皇州。","仍回首，蜀山万点，明月满南楼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-269","tags":[]},{"id":"poem-8624056b0ca80a2e516dcfd1","title":"十二月二十七日趋慈溪","author":"陈造","dynasty":"宋","verses":["西风蜚江浪，江畔那容立。","霰花溅千尺，望望客衣湿。","小舟舣两三，人已鹅鴈集。","侧睨波汹汹，俯怜身岌岌。","乘凌玩掀舞，生死付呼吸。","前登为回首，舟重巾𧥄𧥄。","支径不通车，车去如见絷。","念此役夫苦，体我官事急。","傍顾中夜还，得无僵仆泣。","畀汝就甘寝，白饭亦周给。","徇人多意外，自信宁不及。","利物身每轻，睡觉况六十。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-eee5fa6a-1b5b-4186-8210-f4b77eab2364","tags":[]},{"id":"poem-8626593841fe273b893bff8d","title":"鹧鸪天·十载交盟可重寻","author":"魏了翁","dynasty":"宋","verses":["十载交盟可重寻。","剩于棠茇细论心。","云障晚日供秋思，风递荷书作晚阴。","纡胜引，豁尘襟。","未须紫马去骎骎。","玻璃无计留君住，但乞天公三日霖。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-439","tags":[]},{"id":"poem-8627f90d5935c9ea41504b97","title":"寄法堂颂","author":"智闲","dynasty":"唐","verses":["东间里入寂，西间里语话。","中间里睡眠，通间里行道。","向前即捡校，向后即隐形。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-4634ad48-2906-4448-90c8-13d963d8d125","tags":[]},{"id":"poem-8628767c9b503c659c419950","title":"禁署早春晴望","author":"刘得仁","dynasty":"唐","verses":["御林闻有早莺声，玉槛春香九陌晴。","寒著霁云归紫阁，暖浮佳气动芳城。","宫池日到冰初解，辇路风吹草欲生。","鸳侣此时皆赋咏，商山雪在思尤清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-0864c886-51ed-4774-979c-f3503805d74f","tags":[]},{"id":"poem-862b327f54fb68867465bffa","title":"李端公","author":"卢纶","dynasty":"唐","verses":["故关衰草遍，离别自堪悲。","路出寒云外，人归暮雪时。","少孤为客早，多难识君迟。","掩泪空相向，风尘何处期。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f4301f96-e872-4eae-aa51-0d12328059d1","tags":["冬天","友情","送别","唐诗三百首","五言律诗","伤怀"]},{"id":"poem-862e4431338b16a28b97a61b","title":"十诗谢廖计使  其五","author":"陈造","dynasty":"宋","verses":["我生守荒学，意造无根蔕。","时时写所蕴，致远终恐泥。","小劳斲鼻巧，霜风扫氛翳。","一言可终身，万金宁良惠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-cf0771a3-ef47-44e4-b791-415cdda97f5b","tags":[]},{"id":"poem-86313c4a6afe4053a3d59ee9","title":"海庄观稼","author":"释居简","dynasty":"宋","verses":["东输三十六谿湍，海若谽谺不足吞。","我有黄云连断岸，夜深随月看潮痕。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9e773072-303e-41e5-a182-d4e0779fc8d8","tags":[]},{"id":"poem-863df8914d8a6e860eefca47","title":"鼓吹曲辞 有所思","author":"李白","dynasty":"唐","verses":["我思仙人，乃在碧海之东隅。","海寒多天风，白波连山倒蓬壶。","长鲸喷涌不可涉，抚心茫茫泪如珠。","西来青鸟东飞去，愿寄一书谢麻姑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-4f876a76-9628-4cc3-91da-124444b562f1","tags":[]},{"id":"poem-863e5ddbb10b5059433235a9","title":"品令·露晞烟静","author":"方千里","dynasty":"宋","verses":["露晞烟静。","寂寥转、梧桐寒影。","天际历历征鸿近。","被风吹散，声断无行阵。","秋思客怀多少恨。","谩厌厌谁问。","晕残兰炧香消印。","梦魂长定。","愁伴更筹尽。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-568","tags":[]},{"id":"poem-865094a7693510b7bdf5a4f5","title":"诗品二十四则 典雅","author":"司空图","dynasty":"唐","verses":["玉壶买春，赏雨茆屋。","坐中佳士，左右修竹。","白云初晴，幽鸟相逐。","眠琴绿阴，上有飞瀑。","落花无言，人淡如菊。","书之岁华，其曰可读。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0d555cb2-83cb-4962-9048-867be0255a3d","tags":[]},{"id":"poem-8651de708c991292c8b90f4a","title":"苦篁调啸引","author":"李贺","dynasty":"唐","verses":["请说轩辕在时事，伶伦采竹二十四。","伶伦采之自昆丘，轩辕诏遣中分作十二。","伶伦以之正音律，轩辕以之调元气。","当时黄帝上天时，二十三管咸相随。","唯留一管人间吹，无德不能得此管，此管沈埋虞舜祠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-8f6bd03f-8b60-487c-8448-570a10a581a5","tags":[]},{"id":"poem-86587d26f46d8f0f5bce6185","title":"湖南运使程大卿寿","author":"华镇","dynasty":"宋","verses":["时来嘉会一阳新，庆属高门诞哲人。","杞梓挺材周世用，珪璋含德足天纯。","酒熏爱日凝和气，香触寒梅发早春。","密运阴功方寸地，默增遐算有明神。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-da90defd-79fa-494d-9cde-d085bca7d7bf","tags":[]},{"id":"poem-865ba7fdfff1b7a686952022","title":"八六子·喜秋晴","author":"晁补之","dynasty":"宋","verses":["喜秋晴。","淡云萦缕，天高群雁南征。","正露冷初减兰红，风紧潜雕柳翠，愁人漏长梦惊。","重阳景物凄清。","渐老何时无事，当歌好在多情。","暗自想、朱颜并游同醉，官名缰锁，世路蓬萍。","难相见，赖有黄花满把，从教渌酒深倾。","醉休醒。","醒来旧愁旋生。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-187","tags":[]},{"id":"poem-86614de581165d68bbfda625","title":"浣溪沙·银字笙箫小小童","author":"毛滂","dynasty":"宋","verses":["银字笙箫小小童。","梁洲吹过柳桥风。","阿谁劝我玉杯空。","小醉径须眠锦瑟，夜归不用照纱笼。","画船帘卷月明中。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-744","tags":[]},{"id":"poem-8663d291027aec84425a37a7","title":"崇阳道中作四首  其一","author":"李纲","dynasty":"宋","verses":["我行江南春，初见农事作。","及兹旅湖外，秋稻半已获。","隔林闻晚舂，藁秸积篱落。","童稚亦熙熙，田家有余乐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-486e3aa6-03cb-4921-aecc-37767b58ec24","tags":[]},{"id":"poem-8671d3d7825ac56b190831c1","title":"送僧","author":"可止","dynasty":"唐","verses":["四海无拘系，行心兴自浓。","百年三事衲，万里一枝筇。","夜减当晴影，春消过雪踪。","白云深处去，知宿在何峰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-fc170b63-78c7-413b-b7d1-83179175a4a1","tags":[]},{"id":"poem-86732338e9edd9d46d57d224","title":"送卢秀才应举","author":"贯休","dynasty":"唐","verses":["几载阻兵荒，一名终不忘。","还冲猛风雪，如画冷朝阳。","句好慵将出，囊空却不忙。","明年公道日，去去必穿杨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c2101a4d-5354-48a5-8ac8-9af19521caff","tags":[]},{"id":"poem-8677ef80f5bd752daeebc9fc","title":"送窦兵曹","author":"李端","dynasty":"唐","verses":["梨花开上苑，游女著罗衣。","闻道情人怨，应须走马归。","御桥迟日暖，官渡早莺稀。","莫遣佳期过，看看蝴蝶飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e8b648ab-64a5-4200-9a19-f721ca120ffb","tags":[]},{"id":"poem-868ba7ae34a44db14168930e","title":"王叔武示忠州张使君德远近诗次韵三首  其一","author":"曾协","dynasty":"宋","verses":["垂绅立朝著，智略胜吾丘。","列戟分名郡，儿童说细侯。","卷舒谁罣碍，中外且嬉游。","闻说淮南守，天边又拜州。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-008a6c4b-36aa-4ab5-a605-0da9ac877090","tags":[]},{"id":"poem-86912219e4620feb57075fa8","title":"菩萨蛮·阑风伏雨催寒食","author":"纳兰性德","dynasty":"清","verses":["阑风伏雨催寒食，樱桃一夜花狼藉。","刚与病相宜，锁窗薰绣衣。","画眉烦女伴，央及流莺唤。","半晌试开奁，娇多直自嫌。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-175","tags":[]},{"id":"poem-8693220d74c4958c368e82e6","title":"惜奴娇","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["只为家道贫穷，守荆钗裙布，谨身节用。","今为姻眷，惟恐玷辱亲家门风。","［旦］空空，愧乏房奁来陪奉，望高堂垂怜宠。","［合］喜气浓，悄似仙郎仙女，会合仙宫。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8104","tags":[]},{"id":"poem-869d8d7ff2073a8c21fd8a4c","title":"宿报恩寺精舍","author":"畅当","dynasty":"唐","verses":["钟梵送沈景，星多露渐光。","风中兰靡靡，月下树苍苍。","夜殿若山横，深松如涧凉。","羸然虎溪子，迟我一虚床。","杳杳空寂舍，蒙蒙莲桂香。","拥褐依西壁，纱灯霭中央。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-ac2183df-331b-4594-a1dd-0498da05e189","tags":[]},{"id":"poem-86a3717d3c7d6ed9be978a87","title":"临江仙·绿蚁浮觞香泛泛","author":"张纲","dynasty":"宋","verses":["绿蚁浮觞香泛泛，黄花共荐芳辰。","清霜天宇净无尘。","登高宜有赋，拈笔戏成文。","可奈园林摇落尽，悲秋意与谁论。","眼中相识几番新。","龙山高会处，落帽定何人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-645","tags":[]},{"id":"poem-86b1ef43172aece3387fa7f8","title":"正月十四日大雪上信国公冢  其四","author":"赵文","dynasty":"宋","verses":["十年目与肠俱断，不见延平病雁回。","若不从公天上去，定应随我雪中来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-07353782-41ce-43d7-9ae9-ef6596c2b414","tags":[]},{"id":"poem-86b4e712ec3ed3b1014c45a6","title":"偈","author":"释智勤","dynasty":"宋","verses":["今年五十五，脚未蹋寸土。","山河是眼睛，大海是我肚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-ee6b786e-6291-456a-9475-55ee104c7f06","tags":[]},{"id":"poem-86db9944c578729c8565b99b","title":"赠浙西顾推官","author":"徐铉","dynasty":"宋","verses":["盛府宾寮八十余，闭门高卧兴无如。","梁王苑里相逢早，涧浦城中得信疏。","狼藉杯盘重会面，风流才调一如初。","愿君百岁犹强健，他日相寻隠士庐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-9c4de8b9-7944-4331-b2e2-0cffc686c8e2","tags":[]},{"id":"poem-86e5704e56999f8c9ac7a9e9","title":"庭燎","author":"佚名","dynasty":"先秦","verses":["夜如何其？夜未央，庭燎之光。君子至止，鸾声将将。","夜如何其？夜未艾，庭燎晣晣。君子至止，鸾声哕哕。","夜如何其？夜乡晨，庭燎有辉。君子至止，言观其旗。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-181","tags":[]},{"id":"poem-86f1a0d8dae77e71a86eb3b6","title":"郊庙歌辞 周宗庙乐舞辞 咸顺","author":"不详","dynasty":"唐","verses":["万舞咸列，三阶克清。","贯珠一倡，击石九成。","盈觞虽酌，灵坐无形。","永怀我祖，达其孝诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ed40a913-e197-4ac1-85bd-d82dd147bede","tags":[]},{"id":"poem-86f1e9e94ef9cf1e810cb06d","title":"寄外甥苗武仲","author":"徐铉","dynasty":"宋","verses":["放逐今来涨海边，亲情多在凤台前。","且将聚散为闲事，须信华枯是偶然。","蝉噪疏林村倚郭，鸟飞残照水连天。","此中唯欠韩康伯，共对秋风咏数篇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-4f917d6a-2317-4d38-9e09-284f106acd85","tags":[]},{"id":"poem-86f79341a7b3e53e726e476b","title":"何彼襛矣","author":"佚名","dynasty":"先秦","verses":["何彼襛矣，唐棣之华？曷不肃雍？王姬之车。","何彼襛矣，华如桃李？平王之孙，齐侯之子。","其钓维何？维丝伊缗。齐侯之子，平王之孙。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-23","tags":[]},{"id":"poem-870560b2551e3136bfbfb4a4","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十九","author":"易静","dynasty":"唐","verses":["六仪刑，谋事总难成。","遇着此时遭失陷，奇门虽有也难生（川本作「禁」），大忌用兵行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6ac47fb5-1fbb-4e19-9f88-9921be34bdfd","tags":[]},{"id":"poem-87076950f966c115b71bfe47","title":"绵蛮","author":"佚名","dynasty":"先秦","verses":["绵蛮黄鸟，止于丘阿。道之云远，我劳如何。饮之食之，教之诲之。命彼后车，谓之载之。","绵蛮黄鸟，止于丘隅。岂敢惮行，畏不能趋。饮之食之。教之诲之。命彼后车，谓之载之。","绵蛮黄鸟，止于丘侧。岂敢惮行，畏不能极。饮之食之，教之诲之。命彼后车，谓之载之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-229","tags":[]},{"id":"poem-870f64fce974d76f67eaaa90","title":"长沙郡丞丁君挽词","author":"张栻","dynasty":"宋","verses":["廉吏今尤重，朝家诏举频。","方看千里驾，忽尽百年身。","职业忧劳甚，游从笑语真。","空令行路叹，没后见清贫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-8fcf344f-39e6-4ece-adc4-59964577a8fa","tags":[]},{"id":"poem-8713def846b5772fc11c6572","title":"凤楼春·凤髻绿云丛","author":"欧阳炯","dynasty":"五代","verses":["凤髻绿云丛，深掩房栊。","锦书通，梦中相见觉来慵，匀面泪脸珠融。","因想玉郎何处去，对淑景谁同。","小楼中，春思无穷。","倚栏颙望，暗牵愁绪，柳花飞起东风。","斜日照帘，罗幌香冷粉屏空。","海棠零落，莺语残红。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-12","tags":[]},{"id":"poem-8713ffc0acccde4804026151","title":"于中好·咏史","author":"纳兰性德","dynasty":"清","verses":["马上吟成促渡江，分明闲气属闺房。","生憎久闭金铺暗，花冷回心玉一床。","添哽咽，足凄凉。","谁教生得满身香。","只今西海年年月，犹为萧家照断肠。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-214","tags":[]},{"id":"poem-871af494186a78eeb4605ddc","title":"寓吟集","author":"崔道融","dynasty":"唐","verses":["陶集篇篇皆有酒，崔诗句句不无杯。","醉来已共身安约，让却诗人作酒魁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-cd25b8b0-12a6-4e4a-afd5-6d8a81d814dd","tags":[]},{"id":"poem-872086bcddd662ca2698455a","title":"浣溪沙·元是昭阳宫里人","author":"曾觌","dynasty":"宋","verses":["元是昭阳宫里人。","惊鸿宛转掌中身。","只疑飞过洞庭云。","按彻凉州莲步紧，好花风袅一枝新。","画堂香暖不胜春。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-359","tags":["洞庭湖"]},{"id":"poem-8723864a95d4142e133fc004","title":"南池杂咏五首 溪云","author":"皎然","dynasty":"唐","verses":["舒卷意何穷，萦流复带空。","有形不累物，无迹去随风。","莫怪长相逐，飘然与我同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f1528b27-d4f2-458c-b755-c60c0e53a111","tags":[]},{"id":"poem-872982446501489ac6065631","title":"点绛唇·回雁风微","author":"晁补之","dynasty":"宋","verses":["回雁风微，养花浓淡天容好。","似春知道。","吉梦佳辰到。","共乐春台，携手蓬莱小。","同倾祷。","愿春不老。","岁岁寻芳草。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-244","tags":[]},{"id":"poem-872f8e3f723d91c1304b3e90","title":"前出塞九首 五","author":"杜甫","dynasty":"唐","verses":["迢迢万余里，领我赴三军。","军中异苦乐，主将宁尽闻。","隔河见胡骑，倏忽数百群。","我始为奴仆，几时树功勋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9434b028-3ff5-4d33-866b-e0e2b2d6dc70","tags":[]},{"id":"poem-8737836f4c5abd78b3f8a6d0","title":"观妓","author":"司空曙","dynasty":"唐","verses":["翠蛾红脸不胜情，管绝弦余发一声。","银烛摇摇尘暗下，却愁红粉泪痕生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a66209d3-155e-41b7-b272-8344f078847c","tags":[]},{"id":"poem-874647a41c30c24bfc03deb5","title":"又","author":"释了惠","dynasty":"宋","verses":["转脑回头，百般卖弄。","滞货只些儿，尽力拽不动。","吽吽，我不信得恁么郑重。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-eda8adb0-dbd3-4122-82c8-70fdb318d499","tags":[]},{"id":"poem-8751fe4a7dc266862507ca80","title":"朝中措·功名虽未压英游","author":"曾觌","dynasty":"宋","verses":["功名虽未压英游。","一种旧风流。","人世百年须到，如今七十春秋。","当时帷幄，貂珰贵重，誉蔼朋俦。","赢得尊前沈醉，浮华付去悠悠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-404","tags":[]},{"id":"poem-875e4c547e5debd0d198a877","title":"寒食书事二首 二","author":"张籍","dynasty":"唐","verses":["出城烟火少，况复是今朝。","闲坐将谁语，临觞只自谣。","堦前春藓徧，衣上落花飘。","妓乐州人戏，使君心寂寥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-186a3ef0-4ea6-4e6d-a87e-e60fd78cb793","tags":[]},{"id":"poem-8771d2e3f3ee235a26a7d946","title":"冬尽","author":"吕从庆","dynasty":"唐","verses":["一年惟腊在，忽忽又将央。","雪重庭枝折，风轻径蘂香。","感时空有恨，留岁竟无方。","老矣当樽客，他乡作故乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3fd5e001-3153-44a0-a1ae-c3b1da9d1b47","tags":[]},{"id":"poem-8789440cae6e6d67247c1968","title":"永遇乐·千古江山","author":"辛弃疾","dynasty":"宋","verses":["千古江山，英雄无觅，孙仲谋处。","舞榭歌台，风流总被，雨打风吹去。","斜阳草树，寻常巷陌，人道寄奴曾住。","想当年，金戈铁马，气吞万里如虎。","元嘉草草，封狼居胥，赢得仓皇北顾。","四十三年，望中犹记，烽火扬州路。","可堪回首，佛狸祠下，一片神鸦社鼓。","凭谁问，廉颇老矣，尚能饭否。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-60","tags":["宋词三百首"]},{"id":"poem-878d00865656852b37eea6c3","title":"就以道池上假山","author":"释居简","dynasty":"宋","verses":["数朵忽横翔，云生午树凉。","恍如江上画，移向泽中藏。","絮落鱼翻影，花飞蝶趁香。","却疑闲日月，只在此间长。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-091360f1-7698-49e1-89f9-4a0711e2b73f","tags":[]},{"id":"poem-878f696b5c93dc63b88195d1","title":"好姐姐","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外］听吾一言说与，那王秀才欲求科举。","他若去时，必定家空虚。","［合］堪忧虑，形只影单添凄楚，暮想朝思愈困苦。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8111","tags":[]},{"id":"poem-879010c96d14bcef8de4ec99","title":"过上天竺寺","author":"张栻","dynasty":"宋","verses":["上竺诸天近，中林万木低。","迥超尘世外，恍入雪山西。","忽漫参龙象，行将混鹿麋。","何年释簪绂，于此独幽栖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-ddf9ab0b-5ada-45ad-a031-73d60a9064e4","tags":[]},{"id":"poem-87948dfdd22f4493a2a83c64","title":"送孟寂赴举","author":"孟郊","dynasty":"唐","verses":["烈士不忧身，为君吟苦辛。","男儿久失意，宝剑亦生尘。","浮俗官是贵，君子道所珍。","况当圣明主，岂乏证玉臣。","浊水无白日，清流鉴苍旻。","贤愚皎然别，结交当有因。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a5149be2-c4a5-481a-a7fe-45cf35f6986a","tags":[]},{"id":"poem-8797e6bebc33d1c549a05292","title":"住山后作（题从《小草斋诗话》卷四）","author":"义存","dynasty":"唐","verses":["光阴倏忽（《小草斋诗话》作「迅速」）暂须臾，浮世那（《小草斋诗话》作「何」）能得久居。","出岭年登（《祖庭事苑》卷四作「始年」）三十二，入闽（《祖庭事苑》作「如今」）蚤是四旬余。","他非不用频频检（《祖庭事苑》、《小草斋诗话》作「举」），已过还（《祖庭事苑》作「当」）须旋旋除。","为报满朝（《小草斋诗话》作「报与满朝」）朱紫道，阎王（《祖庭事苑》作「罗」）不怕佩金鱼。","（按：《语录》原缺题。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7abced8e-c238-46ab-83e8-f2edf0e26841","tags":[]},{"id":"poem-879999627d036338263fac9e","title":"省题诗二十一首 元日端门肆赦","author":"王棨","dynasty":"唐","verses":["史官开圣历，天子御层楼。","寿[域]（城）南山色，恩波东海流。","绕栏生杞梓，当槛簇貔貅。","日月祥光近，山河喜气浮。","兆人瞻鳯扆，万里御皇猷。","欲识春生处，鸡竿最上头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8839db68-623b-4b0d-ad1b-91bd362fca91","tags":[]},{"id":"poem-87af48b44f0968b33c429296","title":"载驱","author":"佚名","dynasty":"先秦","verses":["载驱薄薄，簟茀朱鞹。鲁道有荡，齐子发夕。","四骊济济，垂辔沵沵。鲁道有荡，齐子岂弟。","汶水汤汤，行人彭彭。鲁道有荡，齐子翱翔。","汶水滔滔，行人儦儦。鲁道有荡，齐了游敖。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-104","tags":[]},{"id":"poem-87c03ee1f9292c71123c719d","title":"车遥遥","author":"胡曾","dynasty":"唐","verses":["自从车马出门朝，便入空房守寂寥。","玉枕夜残鱼信绝，金钿秋尽雁书遥。","脸边楚雨临风落，头上春云向日销。","芳草又衰还不至，碧天霜冷转无憀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-45f4448e-7f26-41ff-a75f-91dfbdd58c04","tags":[]},{"id":"poem-87c6fbe0f33e5450098be320","title":"贻住山僧","author":"曹松","dynasty":"唐","verses":["罢讲巡岩坞，无穷得野情。","腊高犹伴鹿，夏满不归城。","云朵缘崖发，峰阴截水清。","自然双洗耳，唯任白毫生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-bffe88b3-c216-4a63-b137-87b8afe3abd4","tags":[]},{"id":"poem-87c755bf4c868eaca0754b00","title":"下泉","author":"佚名","dynasty":"先秦","verses":["冽彼下泉，浸彼苞稂。忾我寤叹，念彼周京。","冽彼下泉，浸彼苞萧。忾我寤叹，念彼京周。","冽彼下泉，浸彼苞蓍。忾我寤叹，念彼京师。","芃芃黍苗，阴雨膏之。四国有王，郇伯劳之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-152","tags":[]},{"id":"poem-87cefe4ff450651e30c25a6d","title":"失调名·遥想天孙离别后","author":"宝月","dynasty":"宋","verses":["遥想天孙离别后，一宵欢会，暂停极杼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-857","tags":[]},{"id":"poem-87d05bb499b46cb0f20f5cad","title":"采桑子·谢家庭院残更立","author":"纳兰性德","dynasty":"清","verses":["谢家庭院残更立，燕宿雕梁。","月度银墙。","不辨花丛那辨香。","此情已自成追忆，零落鸳鸯。","雨歇微凉。","十一年前梦一场。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-89","tags":[]},{"id":"poem-87d94cb5fac5e396932fc184","title":"临江仙·昨夜个人曾有约","author":"纳兰性德","dynasty":"清","verses":["昨夜个人曾有约，严城玉漏三更。","一钩新月几疏星。","夜阑犹未寝，人静鼠窥灯。","原是瞿唐风间阻，错教人恨无情。","小阑干外寂无声。","几回肠断处，风动护花铃。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-119","tags":[]},{"id":"poem-87e5b34aab6534060013f9cc","title":"折杨柳","author":"徐延寿","dynasty":"唐","verses":["大道连国门，东西种杨柳。","葳蕤君不见，袅娜垂来久。","缘枝栖暝禽，雄去雌独吟。","余花怨春尽，微月起秋阴。","坐望窗中蝶，起攀枝上叶。","好风吹长条，婀娜何如妾。","妾见柳园新，高楼四五春。","莫吹胡塞曲，愁杀陇头人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-3c4b7c86-882b-4525-a284-f3b3812546d4","tags":[]},{"id":"poem-87e60056caf16bf18926d06f","title":"百丈山","author":"宣宗皇帝","dynasty":"唐","verses":["大雄真迹枕危峦，梵宇层楼耸万般。","日月每从肩上过，山河长在掌中看。","仙峰不间三春秀，灵境何时六月寒？","更有上方人罕到，暮钟朝磬碧云端。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3cc12092-e338-458d-a730-5ee07b08d888","tags":[]},{"id":"poem-87eb83fb2a10bd2819589c66","title":"听弹琴","author":"刘长卿","dynasty":"唐","verses":["泠泠七丝上，静听松风寒。","古调虽自爱，今人多不弹。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-72aab9ef-65a9-4a8a-b36b-61932c09ce85","tags":["唐诗三百首","抒情","音乐","五言绝句"]},{"id":"poem-87f09d94c9ac0b7c22f31448","title":"永明山居诗（六十九首） 六十六","author":"延寿","dynasty":"唐","verses":["得丧从来事甚均，任缘徒用苦劳神。","野蔬随分堪充口，石室依稀可庇身。","碧海几时无去棹，红衢何日息征轮。","若教求道如求利，举世浑成无事人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a70da201-c1cd-4ee0-83fa-5efbff7a70b7","tags":[]},{"id":"poem-87f165e5a48ebfe67afb0f3d","title":"颂古七十六首  其四八","author":"释士珪","dynasty":"宋","verses":["寒时寒，热时热，无寒暑处天然别。","绵州附子汉州姜，打刀须是邠州铁。","洞山老子不瞒人，亲传当面藏身诀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-dbc0c747-f6fb-4fda-8bce-09d6da559292","tags":[]},{"id":"poem-87f1fec0dbc01e8a5a4bce04","title":"宣州开元寺赠惟直上人","author":"许浑","dynasty":"唐","verses":["曾与径山为小师，十年僧行众人知。","夜深月色当禅处，斋后钟声到讲时。","经雨绿苔侵古画，过秋红叶落新诗。","劝君莫厌江城客，虽在风尘别有期。","（见丹徒陈庆年刊《横山草堂丛书》本《许浑诗真迹录》。","）（《全唐诗》卷五二六误作杜牧诗。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c7674015-09cf-4d61-9143-16d4442637c2","tags":[]},{"id":"poem-87fa771a21e63a245ba3373b","title":"杂曲歌辞 渭城曲","author":"王维","dynasty":"唐","verses":["谓城朝雨浥轻尘，客舍青青柳色春。","劝君更尽一杯酒，西出阳关无故人。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e4a87504-f9a3-4599-b770-aba4afd3cb04","tags":["唐诗三百首","八年级下册(课外)","友情","小学古诗","送别","初中古诗","乐府","近代曲辞","四年级上册"]},{"id":"poem-87fadb4895bd49952099c436","title":"寄张仲甫","author":"皇甫曾","dynasty":"唐","verses":["悲风生旧浦，云岭隔东田。","伏腊同鸡黍，柴门闭雪天。","孤村明夜火，稚子候归船。","静者心相忆，离居畏度年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ee1af307-1e4b-4b18-a2d9-1194784cae0a","tags":[]},{"id":"poem-8800725c86a8f3604910c5e7","title":"采芝","author":"赵文","dynasty":"宋","verses":["晨登屋后山，采采山上芝。","可怜松上雨，滴滴沾我衣。","盈筐颇磊落，满意持之归。","童子见我来，拍手共笑之。","薄者实杀人，荡荡光陆离。","厚者不能光，食之有余滋。","我感童子言，叹息成涟洏。","古来用人者，或以薄见奇。","一时误采取，后悔那可追。","乃知古人智，不似童子痴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-731eb499-56d8-4107-bf24-608913fe1280","tags":[]},{"id":"poem-880c954a6481a4ea3875674f","title":"祈雨坛","author":"陈岩","dynasty":"宋","verses":["万感生于一念间，炷香惊起老龙蟠。","今年人协嘉鱼梦，荒却池前古石坛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-52986587-32bc-41d2-93c8-e276b304f399","tags":[]},{"id":"poem-880e057281661b8e5f27e996","title":"泛舟循惠间山水清绝口号四首  其一","author":"李纲","dynasty":"宋","verses":["雨过溪流没旧滩，舟行竟日画图间。","重重翠绿相环揖，卧看王维著色山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-f390e1fc-2459-4820-93a4-fb455e963329","tags":[]},{"id":"poem-880ebb9d1b9f812203310a4d","title":"生查子","author":"施惠《幽闺记》","dynasty":"元","verses":["(老旦上)行寻行又寻。","瑞兰！(小旦内应科。","老旦)远远闻人应。","瑞兰！(小旦应上)呼唤瑞莲名，听了还重省。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2948","tags":[]},{"id":"poem-88183768ae809225207faece","title":"句  其一","author":"李昉","dynasty":"宋","verses":["水光先见月，露气早知秋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-075640d7-9dba-434b-9d8d-087748430a72","tags":[]},{"id":"poem-8826ad55ec89a8191f6bdc96","title":"次韵程帅","author":"陈造","dynasty":"宋","verses":["嗜欲割去土与泥，调虞气血等稚儿。","拘拘谫谫世所怪，未免鹤发仍鸡皮。","甘脆为目不为腹，蚕茧自缚良苦之。","两螯公子大于扇，九室春色堪为池。","开缄况读万选句，快意领此一段奇。","自怜忍欲忍艾似，涎流津饐不自持。","明知喘疾有时愈，更寄斫雪加餐诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-c648e6fc-a18f-4471-97f9-3cd6ac20858f","tags":[]},{"id":"poem-8833b5fbddca82ba8e6a3460","title":"叹昨日三首 二","author":"卢仝","dynasty":"唐","verses":["天下薄夫苦耽酒，玉川先生也耽酒。","薄夫有钱恣张乐，先生无钱养恬漠。","有钱无钱俱可怜，百年骤过如流川。","平生心事消散尽，天上白日悠悠悬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d5179515-796e-467d-b744-3ab3494f1238","tags":[]},{"id":"poem-8837a770ca65ca1febeda7af","title":"题终南山白鹤观","author":"张乔","dynasty":"唐","verses":["上彻炼丹峰，求玄意未穷。","古坛青草合，往事白云空。","仙境日月外，帝乡烟雾中。","人间足烦署，欲去恋松风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-314ee84c-a03c-409b-b13e-fb0a6daeb283","tags":["终南山"]},{"id":"poem-8839857f4c6aeaa350c845fe","title":"麻婆子","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(丑上)画烛画烛光摇映，宾相两边排。","闻知姑娘嫁穷胎，好酒吃大碗，好肉吃大块，吃得桃花上脸来。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8836","tags":[]},{"id":"poem-883a1dec8cb7496feb6988c6","title":"同沈驸马赋得御沟水","author":"李贺","dynasty":"唐","verses":["入苑白泱泱，宫入正靥黄。","遶堤龙骨冷，拂岸鸭头香。","别馆惊残梦，停杯泛小觞。","幸因流浪处，暂得见何郎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-06007eea-c3e4-4a76-86c1-c2917fdff50f","tags":[]},{"id":"poem-883da131084066966f46dcb1","title":"和韦开州盛山十二首 绣衣石榻","author":"张籍","dynasty":"唐","verses":["山城无别味，药草兼鱼果。","时到绣衣人，同来石上坐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ae8591be-54b1-484d-8bde-2ccec2ae987f","tags":[]},{"id":"poem-884316b9d73f3ceb59708c7f","title":"送少隠兄赴兴元幕  其一","author":"张栻","dynasty":"宋","verses":["出手宁嫌晚，论心本不欺。","五年江左客，万里故园思。","肯枉洞庭棹，来寻棠棣诗。","固知名义重，岂但慰朝饥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-2c955e18-ea97-4eb4-b9ad-2106a2eedcd6","tags":["洞庭湖"]},{"id":"poem-8848ecaa4b6287c08bc1f547","title":"思佳客·有约湖山却解襟","author":"高观国","dynasty":"宋","verses":["有约湖山却解襟。","昼眠占得一庭深。","树边风色寒滋味，愁里年华雁信音。","惊楚梦，听瑶琴。","黄花尚可伴孤斟。","断云万一成疏雨，却向湖边看晚阴。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-380","tags":[]},{"id":"poem-8853536d3353cc0d9cd92a71","title":"三层阁上置音声","author":"太宗皇帝","dynasty":"唐","verses":["绮筵移暮景，紫阁引宵烟。","隔栋歌尘合，分阶舞影连。","声流三处管，响乱一重弦。","不似秦楼上，吹箫空学仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e022fa7a-ae8e-49c2-9369-f9d286b972e2","tags":[]},{"id":"poem-886b22e6f4ce1f2ad02ebead","title":"云封庵","author":"徐凝","dynasty":"唐","verses":["登岩背山河，立石秋风里。","隐见浙江涛，一尺东沟水。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-94b5fa09-9eef-4b3c-acc3-99cd9be66a57","tags":[]},{"id":"poem-8875a3e63327bcc752277a1d","title":"高阳台·照野旌旗","author":"周密","dynasty":"宋","verses":["照野旌旗，朝天车马，平沙万里天低。","宝带金章，尊前茸帽风。","秦关汴水经行地，想登临、都付新诗。","纵英游，叠鼓清笳，骏马名姬。","酒酣应对燕山雪，正冰河月冻，晓陇云飞。","投老残年，江南谁念方回。","东风渐绿西湖柳，雁已还、人未南归。","最关情，折尽梅花，难寄相思。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-97","tags":["宋词三百首","西湖"]},{"id":"poem-887f305a519bfd4d3ef0e558","title":"句 二","author":"沈彬","dynasty":"唐","verses":["更好碧溪深院静。","（《江湖小集》卷七绍嵩《江浙纪行集句诗》引。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-060cf73a-dc21-4376-93b3-b2581ff1c16d","tags":[]},{"id":"poem-8881dc2d11d158de3b07e481","title":"□□","author":"佚名","dynasty":"唐","verses":["愤闷屡纵横，愁深百计生。","相思凡几度，慷慨至三更。","虏塞饶白刾，戎乡多紫荆。","关山尔许远，魂梦若为行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3d7b1f88-33d2-4b96-93e4-b524381c42cb","tags":[]},{"id":"poem-8894994bc4304e8a3ce95106","title":"松图  其一","author":"释居简","dynasty":"宋","verses":["李怀仁画双龙后，活在兰陵道士家。","水墨工夫能幻巧，变成霜干老槎牙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-67087e9c-730a-44f9-955a-06472848e06e","tags":[]},{"id":"poem-8895b49cd844fce19c981176","title":"河传·风飐","author":"孙光宪","dynasty":"五代","verses":["风飐，波敛。","团荷闪闪，珠倾露点。","木兰舟上，何处吴娃越艳，藕花红照脸。","大堤狂杀襄阳客，烟波隔，渺渺湖光白。","身已归，心不归。","斜晖，远汀㶉𫛶飞。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-49","tags":[]},{"id":"poem-889ade3539323e9920833d7f","title":"客亭对月","author":"李洞","dynasty":"唐","verses":["游子离魂陇上花，风飘浪卷遶天涯。","一年十二度圆月，十一回圆不在家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ad66e2cd-4bd3-4ca9-ac5b-4b6b69892d50","tags":[]},{"id":"poem-88a5f30e94bb17df169c6ad5","title":"正月偶示颂","author":"文益","dynasty":"唐","verses":["正月春，顺时节。","情有无，皆含悦。","君要知，得谁力。","更问谁，教谁决。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-588a71e3-173a-4f5a-96d2-a5240cd23fc0","tags":[]},{"id":"poem-88a63655bf713abad2386399","title":"下第后归永乐里自题二首 二","author":"赵嘏","dynasty":"唐","verses":["玄发侵愁忽似翁，暖尘寒袖共东风。","公卿门户不知处，立马九衢春影中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-9a806597-f7f6-4f1e-b033-57b757ce1bfd","tags":[]},{"id":"poem-88a6d863115db0de14114356","title":"杂诗四首  其一","author":"李涛","dynasty":"宋","verses":["滔滔东流水，赴海无归期。","亭亭右转日，今兹复来兹。","人生寄天地，百年七十稀。","思虑复营营，恐为达此嗤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-7b4d7315-69ed-4d68-8876-37bcba9fed9f","tags":[]},{"id":"poem-88b6f627a377da99f10e363c","title":"谒江渎庙","author":"喻汝砺","dynasty":"宋","verses":["坤轴东南倾，大江日夜注。","前驱下荆巫，余涛略吴楚。","任势不期劳，得意缘所遇。","水也初无营，神哉亮谁主。","芳兰沉清华，碧藻舒翠缕。","晨鹄戏野岸，春凫集深渚。","均是得所安，而神岂私汝。","古来几精魂，舍此迷所处。","淫游不知还，沙村失烟树。","而我后千载，悠然在江浒。","抱啬贵无竞，矜名忌多取。","冥冥罨岸风，淫淫打船雨。","舞雪窥洪涛，开苹渡前浦。","再拜谢神贶，聊复随所住。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-2bb24a64-8d8b-45ae-8581-38808c02d112","tags":[]},{"id":"poem-88bc838afce69a7ce5be4d80","title":"诉衷情·清晨帘幕卷轻霜","author":"欧阳修","dynasty":"宋","verses":["清晨帘幕卷轻霜。","呵手试梅妆。","都缘自有离恨，故画作远山长。","思往事，惜流芳。","易成伤。","拟歌先敛，欲笑还颦，最断人肠。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-170","tags":["宋词三百首"]},{"id":"poem-88bcb35cea76be4c121fff01","title":"雨霖铃·寒蝉凄切","author":"柳永","dynasty":"宋","verses":["寒蝉凄切。","对长亭晚，骤雨初歇。","都门帐饮无绪，留恋处、兰舟催发。","执手相看泪眼，竟无语凝噎。","念去去、千里烟波，暮霭沈沈楚天阔。","多情自古伤离别。","更那堪、冷落清秋节。","今宵酒醒何处，杨柳岸、晓风残月。","此去经年，应是良辰、好景虚设。","便纵有、千种风情，更与何人说。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-142","tags":["宋词三百首"]},{"id":"poem-88c2ef8994b11ac929267191","title":"书灵筵手巾","author":"后主煜","dynasty":"唐","verses":["浮生共顦顇，壮岁失婵娟。","汗手遗香渍，痕眉染黛烟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a1bfef77-89cd-4e38-90b7-bc41784d58de","tags":[]},{"id":"poem-88c2f18053d59b9311284ace","title":"用韵谢越帅程给事","author":"华镇","dynasty":"宋","verses":["大屏元侯重荐论，自惭蹇浅匪多闻。","已当壮齿逢清世，敢向南山恋白云。","宴以笙簧终永日，宠将珠玉焕新文。","愿凭陶铸冲天去，黄阁门前拜使君。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-e628ea55-f6f8-484e-9afc-95a1784b80bd","tags":[]},{"id":"poem-88c72164c4c93bce897136f8","title":"六言颂六首赠安国觉老  其一","author":"李纲","dynasty":"宋","verses":["大虚一点真气，都卢半掬水中。","堪笑钟离散汉，付与安国秃翁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-47a36c4e-1f29-4551-9b2c-6c87b93ce95a","tags":[]},{"id":"poem-88d8d39d60d1f736904bd318","title":"湘妃庙","author":"李涉","dynasty":"唐","verses":["班竹林边有古祠，鸟啼花发尽堪悲。","当时惆怅同今日，南北行人可得知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-0bd9e0ad-b498-479b-a5b6-f2c43a868013","tags":[]},{"id":"poem-88da7b92e32d6affa6bbf5b2","title":"帆游山","author":"张又新","dynasty":"唐","verses":["涨海尝从此地流，千帆飞过碧山头。","君看深谷为陵后，翻覆人间未肯休。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e8da3bba-9c1e-4ec1-92cf-469e04ff4c5b","tags":[]},{"id":"poem-88ddacc3d67976ea38b4cd8a","title":"念奴娇·轻雷骤雨","author":"蔡伸","dynasty":"宋","verses":["轻雷骤雨，洗千岩浓翠，层峦森列。","衣袂凉生，丛竹外、时有飞萤明灭。","云浪鳞鳞，兰舟泛泛，共载一轮月。","五湖当日，未应此段奇绝。","归路横玉惊鸾，叫云清似水，悠扬天末。","玉宇琼林凝望处，依约广寒宫阙。","老去情锺，此心仍在，未肯甘华发。","清欢留作，异时嘉话重说。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-937","tags":[]},{"id":"poem-88dde915e5498ea4c859b092","title":"留客住·嗟乌兔","author":"周邦彦","dynasty":"宋","verses":["嗟乌兔。","正茫茫、相催无定，只恁东生西没，半均寒暑。","昨见花红柳绿，处处林茂。","又睹霜前篱畔，菊散馀香，看看又还秋暮。","忍思虑。","念古往贤愚，终归何处。","争似高堂，日夜笙歌齐举。","选甚连宵彻昼，再三留住。","待拟沈醉扶上马，怎生向、主人未肯交去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-491","tags":[]},{"id":"poem-88ddecaa2999bea88b882f5e","title":"卜算子·数尽万般花","author":"曾觌","dynasty":"宋","verses":["数尽万般花，不比梅花韵。","雪压风欺恁地寒，划地清喷香。","半醉折归来，插向乌云鬓。","不是愁人闷带花，花带愁人闷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-421","tags":[]},{"id":"poem-88fc01f42dbe89c941a74cb6","title":"次韵陈蒙城金风堂射饮","author":"苏颂","dynasty":"宋","verses":["南都绿蚁封初拆，西圃芳条换新碧。","宾僚相遇惜余春，樽俎留连因促席。","百夫决拾看和容，何用娱宾循饮格。","前者新诗严武事，几日毬场较锋镝。","幕中頼有从事贤，抱器逢时隼当射。","聊从把酒发笑谈，岂独鸣弦观准的。","分明争计算多少，举令都忘歌节拍。","蒙邑大夫富才艺，早擅词林名藉藉。","昨来州序偶淹留，幸接话言逾宿昔。","行筹不必苦辞觞，得隽况曾先射泽。","多惭病守鲜欢悰，出口无奇但喑哑。","贪荣窃禄未能归，每听春禽愁杜魄。","今朝何似强开颜，为喜尊前有嘉客。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-d5720ae8-9806-43ae-8f6d-a24038682b4f","tags":[]},{"id":"poem-890c67e42e6f884780276931","title":"咏史诗 会稽山","author":"胡曾","dynasty":"唐","verses":["越王兵败已山栖，岂望全生出会稽。","何事夫差无远虑，更开罗网放鲸鲵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-06a87924-9f8e-4275-b941-00840794999e","tags":[]},{"id":"poem-890caa557bb9ab4ca2234030","title":"虞美人·落花已作风前舞","author":"叶梦得","dynasty":"宋","verses":["落花已作风前舞。","又送黄昏雨。","晓来庭院半残红。","惟有游丝千丈、晴空。","殷勤花下同携手。","更尽杯中酒。","美人不用敛蛾眉。","我亦多情、无奈酒阑时。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-264","tags":["宋词三百首"]},{"id":"poem-890cfdec7b94c9cc58e41878","title":"奉和送金城公主适西蕃应制","author":"赵彦昭","dynasty":"唐","verses":["圣后经纶远，谋臣计划多。","受降追汉策，筑馆许戎和。","俗化乌孙垒，春生积石河。","六龙今出饯，双鹤愿为歌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7bfb9219-ca68-4f1f-81f9-040420daeff7","tags":[]},{"id":"poem-890e8369e4469616e8946b7d","title":"木兰花・玉楼春·黄金万缕风牵细","author":"柳永","dynasty":"宋","verses":["黄金万缕风牵细。","寒食初头春有味。","𣨼烟尤雨索春饶，一日三眠夸得意。","章街隋岸欢游地。","高拂楼台低映水。","楚王空待学风流，饿损宫腰终不似。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-245","tags":[]},{"id":"poem-8915d88d9eba494e5ceb0ad4","title":"净业寺","author":"纳兰性德","dynasty":"清","verses":["红楼高耸碧池深，荷芰生凉豁远襟。","湖色静涵孤刹影，花香暗入定僧心。","经翻佛藏研朱荚，地赐朝家布紫金。","下马长堤一吟望，梵钟杂送海潮音。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-218","tags":[]},{"id":"poem-89164f27394f61a2ffe55175","title":"点绛唇·五夜光寒","author":"纳兰性德","dynasty":"清","verses":["五夜光寒，照来积雪平于栈。","西风何限，自起披衣看。","对此茫茫，不觉成长叹。","何时旦，晓星欲散，飞起平沙雁。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-18","tags":[]},{"id":"poem-892b7c1702830e5b3c0bdd14","title":"逢王泌自东京至","author":"李端","dynasty":"唐","verses":["逢君自乡至，雪涕问田园。","几处生乔木，谁家在旧村。","山峰横二室，水色映千门。","愁见游从处，如今花正繁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0a3c8ec7-42d7-48b9-90df-b961b50d2a28","tags":[]},{"id":"poem-892ef6e041840645027290c5","title":"奉和圣制上巳祓禊应制","author":"崔国辅","dynasty":"唐","verses":["元巳秦中节，吾君灞上游。","鸣銮通禁苑，别馆遶芳洲。","鹓鹭千官列，鱼龙百戏浮。","桃花春欲尽，谷雨夜来收。","庆向尧樽祝，欢从楚棹讴。","逸诗何足对，窅作掩东周。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-031834a5-d244-4311-8c23-9b1c1018960d","tags":[]},{"id":"poem-89376b35df915625b2bc76b5","title":"尾声","author":"杨景贤","dynasty":"元","verses":["拆散了美满并头莲，接上这热莽连枝树，你愿足咱心未足。","鸱枭难和莺燕侣，厕坑里蛆怎和你似水如鱼。","若是到洪都，佥押文书，甚的是六案须知和裣目？这一个屈死的风流丈夫，偷生的愚痴拙妇，谁想俺死和生的夫妇到头疏？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7946","tags":[]},{"id":"poem-89431bb4518de4fb72697063","title":"泣颜回","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(旦)他从早离门儿。","(小生)与谁为伴？(旦)与两个乔人排会，终朝宴乐，他两个却自先回。","若非小叔，险些儿冻死在深雪里。","背归来再生人世，不知他倒在何处？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1772","tags":[]},{"id":"poem-8946ffb2c910d2c978960331","title":"偈颂（幷序○序为南岳齐己撰） 二十三","author":"居遁","dynasty":"唐","verses":["四气吹成物不虚，可怜青叶下垂珠。","虽然种得无心宝，一任傍人恣意须。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d0816932-f6e6-495a-b0d4-274528eb3112","tags":["衡山"]},{"id":"poem-89479a0aea2a9ca6ed25a4f0","title":"句","author":"张洎","dynasty":"唐","verses":["风物一堆灰。","（见《绀珠集》卷十一引《金坡遗事》。","）（〖1〗《金坡遗事》：「张洎文章清赡。","在江南日，将命入贡。","还作十诗以訾诋京师，有『风物一堆灰』句。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-87cfa9ae-0280-4628-83ac-8d52d91c9204","tags":[]},{"id":"poem-894a1e8024eeaf896272dbbc","title":"尾声","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["几年分别无音耗，奈千山万水迢遥。","只为三不从生出这祸苗。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5233","tags":[]},{"id":"poem-8950511d72da8660b5e229f7","title":"和诸庵花光十梅颂  其四","author":"王柏","dynasty":"宋","verses":["不问东风来未，冷冰冰中得意。","谁于笔外相知，更有无味之味。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-5b4e080f-372d-46c9-9855-705b58f2032b","tags":[]},{"id":"poem-8959940b5dd90fa7ff4fe088","title":"凤栖梧・蝶恋花·任在芦花最深处","author":"杜安世","dynasty":"宋","verses":["任在芦花最深处。","浪静风恬，又泛轻舟去。","去到滩头遇俦侣。","散唱狂歌鱼未取。","不把身心干时务。","一副轮竿，莫笑闲家具。","待拟观光佐明主。","将甚医他民病苦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-945","tags":[]},{"id":"poem-895ed940d11284bb48274ab2","title":"好事近·萧寺两珠红","author":"王之望","dynasty":"宋","verses":["萧寺两珠红，欲共晓霞争色。","独占岁寒天气，正群芳休息。","坐中清唱并阳春，写物妙诗格。","霜鬓自羞簪帽，叹如何抛得。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-485","tags":[]},{"id":"poem-8966eefff9678cb2c2476b79","title":"直甫见示次云乞豫章集数诗偶成二小绝因以自喻  其二","author":"林光朝","dynasty":"宋","verses":["莫怪骚人太颉颃，曾闻阿母语刘郎。","神仙本自无言说，尸解由来最下方。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-2c1af715-72ed-4901-bf33-ded79de7f75b","tags":[]},{"id":"poem-896a479d7573c25b66cdcdd0","title":"晚春途中","author":"张公庠","dynasty":"宋","verses":["一年春事又成空，拥鼻微吟半醉中。","夹路桃花风雨过，马啼无处避残红。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-43014744-328c-49e6-8c79-ec0184b0672b","tags":[]},{"id":"poem-896b74aa5a8a27b4a47a0cfb","title":"颂 三","author":"师备","dynasty":"唐","verses":["万里神光顶后相，没顶之时何处望。","事己成，意已（《五灯会元》作「亦」）休，此个从来（《五灯会元》作「来踪」）触处周。","智者聊闻猛（《五灯会元》作「撩著便」）提取，莫待须臾失却头。","（均见《景德传灯录》卷二九。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-bf445ed0-4292-49f4-9338-13d7b9d8e48c","tags":[]},{"id":"poem-896c859a6bee6d33b5b6f18e","title":"春日喜逢乡人刘松","author":"李咸用","dynasty":"唐","verses":["故人不见五春风，异地相逢岳影中。","旧业久抛耕钓侣，新闻多说战争功。","生民有恨将谁诉，花木无情秪自红。","莫把少年愁过日，一尊须对夕阳空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-cc6847e2-8cbc-4c4e-a033-6a8b5b3a1859","tags":[]},{"id":"poem-89712e43d0bdea6e1d43c0dd","title":"游长宁公主流杯池二十五首 七","author":"上官昭容","dynasty":"唐","verses":["莫论圆峤，休说方壶。","何如鲁馆，即是仙都。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c43d47da-630c-4a86-bcf4-f9abf991b6c7","tags":[]},{"id":"poem-8973ac6dc9ac6215f0841381","title":"除日","author":"张子容","dynasty":"唐","verses":["腊月今知晦，流年此夕除。","拾樵供岁火，帖牖作春书。","柳觉东风至，花疑小雪余。","忽逢双鲤赠，言是上冰鱼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-2f5ad030-5bc9-4111-9ca0-757f993ba796","tags":[]},{"id":"poem-89780ad1ff91fcb71459e456","title":"千叶碧桃二绝句  其一","author":"李纲","dynasty":"宋","verses":["春光欲暮碧桃开，烟露相和染玉腮。","仙苑何人移得种，风光疑自茂陵来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-e9908a3c-545b-4fda-a0de-bc68ef9c35f6","tags":[]},{"id":"poem-89780ef2a6b331fd1c630afd","title":"望江南・忆江南·江南草","author":"王琪","dynasty":"宋","verses":["江南草，如种复如描。","深映落花莺舌乱，绿迷南浦客魂消。","日日斗青袍。","风欲转，柔态不胜娇。","远翠天涯经夜雨，冷痕沙上带昏潮。","谁梦与兰苕。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-846","tags":[]},{"id":"poem-897d2c30b2398dd32ecefd84","title":"送萧颖士赴东府得往字","author":"郑愕","dynasty":"唐","verses":["斤溪数亩田，素心拟长往。","繄君曲得引，使我缨俗网。","风尘岂不劳，道义成心赏。","春郊桃李月，忍此戒征两。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-aba90e40-6a95-49eb-9432-5ef7e17a3ee8","tags":[]},{"id":"poem-897e4f482b1039e102a1b047","title":"题南鉴公山房","author":"李洞","dynasty":"唐","verses":["竹房开处峭，迥挂半山灯。","石磬敲来穴，不知何代僧。","讲归双袖雪，禅起一盂冰。","唯说黄桑屐，当时着秣陵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-821466f3-94f7-4479-9bab-43ed2e50618a","tags":[]},{"id":"poem-8983ca2a75354513ba998494","title":"宝陀岩","author":"陈岩","dynasty":"宋","verses":["阴磴层崖洞室宽，奇花异草几多般。","彩云不动金光起，便作金莲法界看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-914ba9b9-16c1-41f9-8a02-eddac60ec4f6","tags":[]},{"id":"poem-8984b151844b3508b49419e5","title":"奉和常阁老晚秋集贤院即事寄赠徐薛二侍郎","author":"包佶","dynasty":"唐","verses":["秘殿掖垣西，书楼苑树齐。","秋烟凝缥帙，晓色上璇题。","门接承明近，池连太液低。","疎钟文马驻，繁叶彩禽栖。","职美纶江綍，荣深组及珪。","九霄偏眷顾，三事早提携。","对案临青玉，窥书捧紫泥。","始欢新遇重，还惜旧游暌。","左宦登吴岫，分家渡越溪。","赋中频叹𫛳，卜处几听鸡。","望阙应多恋，临津不用迷。","柏梁思和曲，朝夕候金闺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-42864ab0-426d-435d-b6e9-81a45a5f225d","tags":[]},{"id":"poem-8989f0e2d25ab7eaf2596316","title":"和君贶题潞公东庄","author":"司马光","dynasty":"宋","verses":["嵩峰远叠千重雪，伊浦低临一片天。","百顷平皋连别馆，两行疏柳拂清泉。","国须柱石扶丕构，人待楼航济巨川。","萧相方如左右手，且于穷僻置闲田。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-daab84ed-bf23-4614-a84e-a3cf367296e8","tags":[]},{"id":"poem-899c8fbea9abfdfcbc57e05e","title":"酬郑毗踯躅咏","author":"孟郊","dynasty":"唐","verses":["不似人手致，岂关地势偏。","孤光褭余翠，独影舞多妍。","迸火烧闲地，红星堕青天。","忽惊物表物，嘉客为留连。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-8e56dba0-eb4e-4785-9f20-7d5a290cc1c1","tags":[]},{"id":"poem-89a9ccd54aafb7eaa1647fbf","title":"夜宿黑灶溪","author":"张籍","dynasty":"唐","verses":["夜到碧溪里，无人秋月明。","逢幽更移宿，取伴亦探行。","花下红泉色，云西乳鹤声。","明朝记归处，石上自书名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-720e3d90-14ad-4393-9163-e063ab3e6783","tags":[]},{"id":"poem-89b636752f5e55c6ed80ef4c","title":"昭君怨·暮雨丝丝吹湿","author":"纳兰性德","dynasty":"清","verses":["暮雨丝丝吹湿，倦柳愁荷风急。","瘦骨不禁秋，总成愁。","别有心情怎说，未是诉愁时节，谯鼓已三更，梦须成。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-56","tags":[]},{"id":"poem-89c5f53a5279a53ece5f5b1b","title":"更漏子 其二","author":"温庭筠","dynasty":"唐","verses":["星斗稀，钟鼓歇，帘外晓莺残月。","兰露重，柳风斜，满庭堆落花。","虚阁上，倚栏望，还似去年惆怅。","春欲暮，思无穷，旧欢如梦中。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-15","tags":[]},{"id":"poem-89c5f9cac8d43d1c3f02293c","title":"送皇甫冉往白田","author":"崔峒","dynasty":"唐","verses":["江边尽日雉鸣飞，君向白田何日归。","楚地蒹葭连海逈，隋朝杨柳映堤稀。","津楼故市无行客，山馆空庭闭落晖。","试问疲人与征战，使君双泪定沾衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-5bdcf9e3-cb35-46e5-ab96-ad215e02f331","tags":[]},{"id":"poem-89d2967258b02612be6c5c8d","title":"浪淘沙·夜雨做成秋","author":"纳兰性德","dynasty":"清","verses":["夜雨做成秋，恰上心头。","教他珍重护风流。","端的为谁添病也，更为谁羞。","密意未曾休，密愿难酬。","珠帘四卷月当楼。","暗忆欢期真似梦，梦也须留。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-115","tags":[]},{"id":"poem-89da5c8145eae7d5fd2478f3","title":"持钵  其二","author":"释居简","dynasty":"宋","verses":["乐岁持盂尚许艰，有求那解破人悭。","立残穰草堆头日，撑尽苹芜断处湾。","钟鼓敢嫌贫指众，斗筲庸恤老腰顽。","归舟只载华亭月，不作华亭误夹山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-00fff8d8-1261-4d53-9d89-dfd541749cba","tags":[]},{"id":"poem-89e4b01a67aad99a1e897b4b","title":"思越人·古台平","author":"孙光宪","dynasty":"五代","verses":["古台平，芳草远，馆娃宫外春深。","翠黛空留千载恨，教人何处相寻。","绮罗无复当时事，露花点滴香泪。","惆怅遥天横绿水，鸳鸯对时飞起。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-39","tags":[]},{"id":"poem-89ec05455ef8a7ab445abb45","title":"寄孙洛阳格","author":"张籍","dynasty":"唐","verses":["久持刑宪声名远，好是中朝正直臣。","赤县上来应足事，青山老去未离身。","常思从省连归马，乍觉同班少旧人。","遥爱南桥秋日晚，雨边杨柳映天津。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0f26e21c-78b1-4f24-be65-7e27ae0d3be0","tags":[]}];
